/** All translations for zizhitongjian ch.026 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起上章涒灘，盡玄黓閹茂，凡三年。", literal: "From Shangzhang Tuntan through Xuanji Yanmao; three years in all.", idiomatic: "From Shangzhang Tuntan through Xuanji Yanmao—three years in all." },
  { zh: "1春，正月，上始行幸甘泉，郊泰畤，三月，行幸河東，祠-{后土}-。", literal: "1. In spring, the first month, the emperor first undertook the journey to favor Sweet Springs and sacrificed at the Great Altar; in the third month he undertook the journey to favor Hedong and sacrificed to -{后土}-.", idiomatic: "1. In spring, the first month, the emperor first traveled to Sweet Springs and sacrificed at the Great Altar; in the third month he traveled to Hedong and sacrificed to -{后土}-." },
  { zh: "上頗修武帝故事，謹齋祀之禮，以方士言增置神祠；", literal: "The emperor largely restored Emperor Wu's practices, carefully observing fasting and sacrificial rites; on the word of fangshi he added divine shrines;", idiomatic: "The emperor largely revived Emperor Wu's ways, carefully observing fasting and sacrifice; on fangshi advice he added shrines;" },
  { zh: "聞益州有金馬、碧雞之神，可醮祭而致，於是遣諫大夫蜀郡王褒使持節而求之。", literal: "hearing that in Yizhou were the spirits of the Golden Horse and Green Cock, whom libation-sacrifice could summon, he thereupon dispatched Remonstrance Grandee Wang Bao of Shu commandery as envoy bearing credentials to seek them.", idiomatic: "hearing that Yizhou held the spirits of the Golden Horse and Green Cock, whom libation could summon, he dispatched Remonstrance Grandee Wang Bao of Shu as envoy bearing credentials to seek them." },
  { zh: "初，上聞褒有俊才，召見，使為《聖主得賢臣頌》。", literal: "Earlier the emperor heard that Bao had outstanding talent, summoned him for audience, and had him compose \"An Ode on the Sage Lord Obtaining Worthy Ministers.\"", idiomatic: "Earlier the emperor heard Bao had outstanding talent, summoned him, and had him compose \"An Ode on the Sage Lord Obtaining Worthy Ministers.\"" },
  { zh: "其辭日：", literal: "Its words read:", idiomatic: "Its words read:" },
  { zh: ":「夫賢者，國家之器用也。", literal: ": \"Worthy men are the state's vessels and tools.", idiomatic: ": \"Worthy men are the state's tools and vessels." },
  { zh: "所任賢，則趨舍省而功施普；", literal: "When the worthy are employed, comings and goings grow spare and merit spreads broadly;", idiomatic: "Employ the worthy, and comings and goings grow lean while merit spreads wide;" },
  { zh: "器用利，則用力少而就效眾。", literal: "when vessels and tools are sharp, little force is spent yet many effects are achieved.", idiomatic: "when tools are sharp, little force yields many results." },
  { zh: "故工人之用鈍器也，勞筋苦骨，終日矻矻；", literal: "Therefore when a craftsman uses blunt tools, he strains sinew and bones and toils all day in ceaseless drudgery;", idiomatic: "When a craftsman uses blunt tools, sinew and bone strain through ceaseless drudgery;" },
  { zh: "及至巧冶鑄干將，使離婁督繩，公輸削墨，雖崇台五層、延袤百丈而不溷者，工用相得也，庸人之御駑馬，亦傷吻、敝策而不進於行；", literal: "but when a skilled smith casts Ganjiang, sets Lü Ou to sight the line, and Gongshu to plane the ink-line, then though a tower rise five tiers and stretch a hundred zhang in length, it will not go awry—for craftsman and tool suit each other. A vulgar man driving a nag also wounds the bit and wears out the whip yet cannot advance on the road;", idiomatic: "but when a skilled smith casts Ganjiang, sets Lü Ou to sight the line, and Gongshu to plane the ink-line, a tower five tiers high and a hundred zhang long will not go awry—craftsman and tool suit each other. A vulgar man driving a nag wounds the bit and wears out the whip yet cannot advance;" },
  { zh: "及至駕嚙膝、驂乘旦，王良執靶，韓哀附輿，周流八極，萬里一息，何其遼哉？", literal: "yet when one yokes Niejie and Chengchengdan, Wang Liang holds the reins, and Han Ai attends the carriage, circling the eight extremities, ten thousand li in a single breath—how vast the reach!", idiomatic: "yet yoke Niejie and Chengchengdan, Wang Liang hold the reins, Han Ai attend the carriage, circle the eight extremities, ten thousand li in a breath—how vast the reach!" },
  { zh: "人馬相得也。", literal: "Man and horse suit each other.", idiomatic: "Man and horse suit each other." },
  { zh: "故服絺綌之涼者，不苦盛暑之鬱燠；", literal: "Therefore one who wears fine hemp's coolness does not suffer the oppressive heat of blazing summer;", idiomatic: "One who wears fine hemp's coolness does not suffer blazing summer's oppressive heat;" },
  { zh: "裘貂狐之暖者，不憂至寒之悽愴。", literal: "one who wears fur, sable, and fox warmth does not grieve the bitter chill of deepest cold.", idiomatic: "one wrapped in fur, sable, and fox does not grieve deepest winter's bitter chill." },
  { zh: "何則？", literal: "Why?", idiomatic: "Why?" },
  { zh: "有其具者易其備。", literal: "Because having the proper means makes preparation easy.", idiomatic: "Having the proper means makes preparation easy." },
  { zh: "賢人、君子，亦聖王之所以易海內也。", literal: "Worthy men and gentlemen are likewise what a sage king uses to bring ease within the seas.", idiomatic: "Worthy men and gentlemen are what a sage king uses to bring ease within the seas." },
  { zh: "昔周公躬吐捉之勞，故有圉空之隆；", literal: "Of old Duke of Zhou personally bore the toil of spitting into his palm and seizing guests' sleeves; therefore he had the grandeur of empty prisons.", idiomatic: "Of old the Duke of Zhou personally bore the toil of spitting into his palm and seizing guests' sleeves; therefore his prisons stood empty." },
  { zh: "齊桓設庭燎之禮，故有匡合之功。", literal: "Duke Huan of Qi established the court-torch rite; therefore he had the achievement of rectifying and uniting.", idiomatic: "Duke Huan of Qi established the court-torch rite; therefore he achieved rectification and union." },
  { zh: "由此觀之，君人者勤於求賢而逸於得人。", literal: "From this to observe, one who rules men toils at seeking the worthy yet rests once the worthy are obtained.", idiomatic: "From this one sees: a ruler toils to seek the worthy yet rests once they are obtained." },
  { zh: "人臣亦然。", literal: "Ministers are likewise.", idiomatic: "Ministers are likewise." },
  { zh: "昔賢者之未遭遇也，圖事揆策，則君不用其謀；", literal: "Of old when worthy men had not yet met their opportunity, they plotted affairs and weighed policies, yet the lord would not use their counsel;", idiomatic: "Of old, before worthy men met their chance, they plotted affairs and weighed policies, yet the lord would not heed their counsel;" },
  { zh: "陳見悃誠，則上不然其信；", literal: "they presented their honest sincerity, yet the ruler would not approve their trustworthiness;", idiomatic: "they offered honest sincerity, yet the ruler would not trust them;" },
  { zh: "進仕不得施效，斥逐又非其愆。", literal: "advancing to office they could not display effect, and when driven off it was not for their fault.", idiomatic: "they could not display their merit in office, and when driven off it was not for any fault of theirs." },
  { zh: "是故伊尹勤於鼎俎，太公困於鼓刀，百里自鬻，寧子飯牛，離此患也。", literal: "Therefore Yi Yin toiled at the sacrificial tripod, Taigong was trapped at the chopping block, Baili sold himself, Ningzi fed oxen—each escaped this affliction.", idiomatic: "Therefore Yi Yin toiled at the sacrificial tripod, Taigong was trapped at the chopping block, Baili sold himself, Ningzi fed oxen—each escaped this affliction." },
  { zh: "及其遇明君、遭聖主也，運籌合上意，諫諍即見聽，進退得關其忠，任職得行其術，剖符錫壤而光祖考。", literal: "When they met an enlightened lord and encountered a sage sovereign, their stratagems matched the ruler's intent; remonstrance was at once heeded; in advance and retreat their loyalty was heeded; in office their arts could be exercised; they were granted tally and fief and their forebears were glorified.", idiomatic: "When they met an enlightened lord and a sage sovereign, their stratagems matched the ruler's intent; remonstrance was heeded at once; advance and retreat answered to their loyalty; in office their arts could be exercised; tally and fief glorified their forebears." },
  { zh: "故世必有聖知之君，而後有賢明之臣。", literal: "Therefore the age must first have a sage and knowing lord, and only then have worthy and enlightened ministers.", idiomatic: "Therefore the age must first have a sage and knowing lord, and only then worthy and enlightened ministers." },
  { zh: "故虎嘯而風冽，龍興而致雲，蟋蟀俟秋吟，蜉蝤出以陰。", literal: "Thus when the tiger roars the wind turns sharp; when the dragon rises clouds gather; the cricket waits for autumn to sing; the mayfly emerges with the shade.", idiomatic: "Thus the tiger's roar sharpens the wind; the dragon's rise gathers clouds; the cricket waits for autumn to sing; the mayfly emerges with the shade." },
  { zh: "《易》曰：『飛龍在天，利見大人。", literal: "The Changes says: \"The flying dragon is in heaven; it profits to see the great man.", idiomatic: "The Changes says: \"The flying dragon is in heaven; it profits to see the great man." },
  { zh: "』《詩》曰：『思皇多士，生此王國。", literal: "\" The Odes says: \"Think how many officers, born for this royal domain.", idiomatic: "\" The Odes says: \"Think how many officers, born for this royal domain." },
  { zh: "』故世平主聖，俊艾將自至。", literal: "\" Therefore when the age is peaceful and the lord sage, outstanding and aged men will come of themselves.", idiomatic: "\" Therefore when the age is peaceful and the lord sage, outstanding men will come of themselves." },
  { zh: "明明在朝，穆穆布列，聚精會神，相得益章，雖伯牙操遞鐘，逢門子彎烏號，猶未足以喻其意也。", literal: "Bright and clear in court, grave and orderly in array, gathering essence and joining spirit, each gaining from the other in splendor—even if Boya played the Dizhong and Fengmenzi bent the Wuhou, it would still not suffice to image their meaning.", idiomatic: "Bright in court, grave in array, gathering essence and joining spirit, each gaining splendor from the other—even if Boya played the Dizhong and Fengmenzi bent the Wuhou, it would not suffice to image their meaning." },
  { zh: "故聖主必待賢臣而弘功業，俊士亦俟明主以顯其德。", literal: "Therefore the sage lord must await worthy ministers to enlarge his achievement; outstanding scholars likewise await an enlightened lord to display their virtue.", idiomatic: "Therefore the sage lord must await worthy ministers to enlarge his achievement; outstanding scholars likewise await an enlightened lord to display their virtue." },
  { zh: "上下俱欲，歡然交欣，千載壹合，論說無疑，翼乎如鴻毛遇順風，沛乎如巨魚縱大壑。", literal: "Above and below alike desire it; they rejoice and exchange delight; once in a thousand years they meet as one; discussion proceeds without doubt—swift as down meeting a fair wind, surging as a great fish released into a vast ravine.", idiomatic: "Above and below alike desire it; they rejoice together; once in a thousand years they meet; discussion proceeds without doubt—swift as down on a fair wind, surging as a great fish in a vast ravine." },
  { zh: "其得意若此，則胡禁不止，曷令不行！", literal: "If their satisfaction is like this, what could be forbidden and not cease, what order could be issued and not carried out!", idiomatic: "When satisfaction runs this deep, what could be forbidden and not cease, what order issued and not obeyed!" },
  { zh: "行溢四表，橫被無窮。", literal: "Their conduct overflows the four quarters; their cover spreads boundlessly.", idiomatic: "Their conduct overflows the four quarters; their cover spreads without end." },
  { zh: "是以聖王不遍窺望而視已明，不殫傾耳而聽已聰，太平之責塞，優遊之望得，休徵自至，壽考無疆，何必偃仰屈伸若彭祖，呴噓呼吸如僑、松，眇然絕俗離世哉！", literal: "Therefore the sage king need not peer everywhere to see clearly, need not strain every ear to hear keenly; the charge of great peace is fulfilled, the hope of ease is obtained, auspicious signs come of themselves, long life knows no bound—why must he bow and stretch like Pengzu, exhale and inhale like Qiao and Song, dimly severing himself from the vulgar world!", idiomatic: "Therefore the sage king need not peer everywhere to see clearly, need not strain every ear to hear keenly; the charge of great peace is fulfilled, ease is obtained, auspicious signs come of themselves, long life knows no bound—why bow and stretch like Pengzu, breathe like Qiao and Song, dimly sever himself from the vulgar world!" },
  { zh: "是時上頗好神仙，故褒對及之。", literal: "At that time the emperor rather favored immortals; therefore Bao's response touched on this.", idiomatic: "At that time the emperor favored immortals; therefore Bao's response touched on this." },
  { zh: "京兆尹張敞亦上疏諫曰：「願明主時忘車馬之好，斥遠方士之虛語，游心帝王之術，太平庶幾可興也。", literal: "Metropolitan Governor Zhang Chang also submitted a memorial remonstrating, saying: \"I wish the enlightened lord would at times forget his fondness for carriages and horses, drive off the empty words of fangshi from afar, and roam his mind in the arts of emperors and kings—then great peace might nearly be raised.", idiomatic: "Metropolitan Governor Zhang Chang also submitted a memorial: \"I wish the enlightened lord would at times forget his fondness for carriages and horses, drive off the empty words of fangshi, and fix his mind on the arts of emperors and kings—then great peace might nearly rise." },
  { zh: "」上由是悉罷尚方待詔，初，趙廣漢死後，為京兆尹者皆不稱職，唯敞能繼其跡；", literal: "\" The emperor thereupon entirely dismissed the Attendants Awaiting Edicts of the Imperial Workshop. Earlier, after Zhao Guanghan died, those made Metropolitan Governor were none fit for office; only Chang could follow in his tracks;", idiomatic: "\" The emperor thereupon dismissed all Attendants Awaiting Edicts of the Imperial Workshop. Earlier, after Zhao Guanghan died, none appointed Metropolitan Governor had been fit for office; only Chang could follow in his tracks;" },
  { zh: "其方略、耳目不及廣漢，然頗以經術儒雅文之。", literal: "his stratagems and eyes and ears did not reach Guanghan's level, yet he largely adorned his rule with classical learning and refined courtesy.", idiomatic: "his stratagems and intelligence did not match Guanghan's, yet he largely adorned his rule with classical learning and refined courtesy." },
  { zh: "----2上頗修飾，宮室、車服盛於昭帝時；", literal: "----2 The emperor largely adorned himself; palace chambers and carriage regalia exceeded those of Emperor Zhao's time;", idiomatic: "----2 The emperor largely adorned himself; palaces and carriage regalia exceeded Emperor Zhao's time;" },
  { zh: "外戚許、史、王氏貴寵。", literal: "the maternal kin—the Xu, Shi, and Wang clans—were honored and favored.", idiomatic: "the maternal Xu, Shi, and Wang clans were honored and favored." },
  { zh: "諫大夫王吉上疏曰：「陛下躬聖質，總萬方，惟思世務，將興太平，詔書每下，民欣然若更生。", literal: "Remonstrance Grandee Wang Ji submitted a memorial, saying: \"Your Majesty personally bears sage substance, holds all directions, and thinks only of the age's affairs, about to raise great peace; whenever an edict descends, the people rejoice as if reborn.", idiomatic: "Remonstrance Grandee Wang Ji submitted a memorial: \"Your Majesty personally bears sage substance, holds all directions, and thinks only of the age's affairs, intent on raising great peace; whenever an edict descends, the people rejoice as if reborn." },
  { zh: "臣伏而思之，可謂至恩，未可謂本務也。", literal: "Your servant bows and reflects: this may be called utmost grace, yet it cannot be called the root task.", idiomatic: "Your servant bows and reflects: this may be called utmost grace, yet it cannot be called the root task." },
  { zh: "欲治之主不世出，公卿幸得遭遇其時，言聽諫從，然未有建萬世之長策，舉明主於三代之隆也。", literal: "Lords who desire good governance do not appear every generation; the duke and ministers are fortunate to meet such a time, their words heard and remonstrance followed—yet none has established a long-range plan for ten thousand generations or raised the enlightened lord to the grandeur of the Three Dynasties.", idiomatic: "Lords who desire good governance do not appear every generation; the duke and ministers are fortunate to meet such a time, their words heard and remonstrance followed—yet none has established a plan for ten thousand generations or raised the enlightened lord to Three Dynasties grandeur." },
  { zh: "其務在於期會、簿書、斷獄、聽訟而已，此非太平之基也。", literal: "Their tasks stop at deadlines, ledgers, judging prison cases, and hearing lawsuits—this is not the foundation of great peace.", idiomatic: "Their tasks stop at deadlines, ledgers, judging cases, and hearing lawsuits—this is not the foundation of great peace." },
  { zh: "臣聞民者，弱而不可勝，愚而不可欺也。", literal: "Your servant has heard that the people are weak yet cannot be overcome, foolish yet cannot be deceived.", idiomatic: "Your servant has heard that the people are weak yet cannot be overcome, foolish yet cannot be deceived." },
  { zh: "聖主獨行於深宮，得則天下稱誦之，失則天下-{咸}-言之，故宜謹選左右，審擇所使。", literal: "The sage lord walks alone in the deep palace; if he gains, all under Heaven praises and recites it; if he errs, all under Heaven -{咸}- speaks of it—therefore he ought carefully to choose those at his side and scrutinize those he employs.", idiomatic: "The sage lord walks alone in the deep palace; if he succeeds, all under Heaven praises it; if he errs, all under Heaven -{咸}- speaks of it—therefore he ought carefully to choose those at his side and scrutinize those he employs." },
  { zh: "左右所以正身，所使所以宣德，此其本也。", literal: "Those at the side are for rectifying the person; those employed are for spreading virtue—this is the root.", idiomatic: "Those at the side rectify the person; those employed spread virtue—this is the root." },
  { zh: "孔子曰：『安上治民，莫善於禮，』非空言也。", literal: "Confucius said: \"To settle those above and govern the people, nothing surpasses ritual\"—this is not empty speech.", idiomatic: "Confucius said: \"To settle those above and govern the people, nothing surpasses ritual\"—this is not empty speech." },
  { zh: "王者未制禮之時，引先王禮宜於今者而用之。", literal: "When a king has not yet fixed ritual, he draws upon former kings' rites suited to the present and employs them.", idiomatic: "When a king has not yet fixed ritual, he draws upon former kings' rites suited to the present and employs them." },
  { zh: "臣願陛下承天心，發大業，與公卿大臣延及儒生，述舊禮，明王制，驅一世之民躋之仁壽之域，則俗何以不若成、康，壽何以不若高宗！", literal: "Your servant wishes Your Majesty would receive Heaven's heart, unfold great enterprise, extend with the duke, ministers, and great officers to the ru scholars, set forth old ritual and clarify kingly institutions, and drive the people of an age into the realm of benevolence and long life—then how could custom fail to match Cheng and Kang, how could longevity fail to match Gaozong!", idiomatic: "Your servant wishes Your Majesty would receive Heaven's heart, unfold great enterprise, extend with duke, ministers, and ru scholars to set forth old ritual and clarify kingly institutions, and drive the people of an age into benevolence and long life—then how could custom fail to match Cheng and Kang, how could longevity fail to match Gaozong!" },
  { zh: "竊見當世趨務不合於道者，謹條奏，唯陛下財擇焉。", literal: "Your servant has observed that the age's pursued tasks do not accord with the Way; he respectfully lists them in memorial—may Your Majesty only choose among them.", idiomatic: "Your servant has observed the age's pursued tasks do not accord with the Way; he respectfully lists them—may Your Majesty choose among them." },
  { zh: "吉意以為：「世俗聘妻、送女無節，則貧人不及，故不舉子。", literal: "Ji was of the opinion: \"When the vulgar world betroths wives and sends off daughters without measure, the poor cannot keep pace and therefore do not rear children.", idiomatic: "Ji was of the opinion: \"When the vulgar world betroths wives and sends off daughters without measure, the poor cannot keep pace and therefore do not rear children." },
  { zh: "又，漢家列侯尚公主，諸侯則國人承翁主，使男事女，夫屈於婦，逆陰陽之位，故多女亂。", literal: "Moreover Han marquises marry imperial princesses; feudal lords then have their people serve the princess as father-in-law, making men serve women and husbands bow to wives—reversing yin and yang's stations—therefore female disorder is frequent.", idiomatic: "Moreover Han marquises marry imperial princesses; feudal lords then have their people serve the princess as father-in-law, making men serve women and husbands bow to wives—reversing yin and yang—therefore female disorder is frequent." },
  { zh: "古者衣服、車馬，貴賤有章；", literal: "Of old clothing and carriage horses had distinctions of noble and base;", idiomatic: "Of old clothing and carriages had distinctions of noble and base;" },
  { zh: "今上下僭差，人人自制，是以貪財誅利，不畏死亡。", literal: "now above and below transgress in gradation and each man makes his own rules—therefore they crave wealth, pursue profit, and do not fear death.", idiomatic: "now above and below transgress in gradation and each man makes his own rules—therefore they crave wealth, pursue profit, and do not fear death." },
  { zh: "周之所以能致治刑措而不用者，以其禁邪於冥冥，絕惡於未萌也。", literal: "Zhou could bring governance to the point that punishments were set aside unused because it forbade wickedness in the hidden dark and cut off evil before it sprouted.", idiomatic: "Zhou could bring governance to the point that punishments lay unused because it forbade wickedness in the hidden dark and cut off evil before it sprouted." },
  { zh: "」又言：「舜、湯不用三公、九卿之世而舉皋陶、伊尹，不仁者遠。", literal: "\" He also said: \"Shun and Tang did not use men from generations of Three Dukes and Nine Ministers but raised Gao Yao and Yi Yin—the unbenevolent stood far off.", idiomatic: "\" He also said: \"Shun and Tang did not use men from generations of Three Dukes and Nine Ministers but raised Gao Yao and Yi Yin—the unbenevolent stood far off." },
  { zh: "今使俗吏得任子弟，率多驕驁，不通古今，無益於民，宜明選求賢，除任子之令；", literal: "Now if vulgar officials may place their sons in office, they are mostly arrogant and unruly, unversed in past and present, of no benefit to the people—it is fitting clearly to select and seek the worthy and abolish the ordinance on appointing sons;", idiomatic: "Now if vulgar officials may place their sons in office, they are mostly arrogant and unruly, unversed in past and present, of no benefit to the people—it is fitting clearly to select the worthy and abolish the ordinance on appointing sons;" },
  { zh: "外家及故人，可厚以財，不宜居位。", literal: "maternal kin and old acquaintances may be richly rewarded with wealth but should not hold office.", idiomatic: "maternal kin and old acquaintances may be richly rewarded but should not hold office." },
  { zh: "去角抵，減樂府，省尚方，明示天下以儉。", literal: "Remove horn-butting contests, reduce the Music Bureau, cut the Imperial Workshop, and show all under Heaven plainly that thrift is the rule.", idiomatic: "Remove horn-butting contests, reduce the Music Bureau, cut the Imperial Workshop, and show the realm plainly that thrift is the rule." },
  { zh: "古者工不造雕瑑，商不通侈靡，非工、商之獨賢，政教使之然也。", literal: "Of old craftsmen did not make carved inlay and merchants did not traffic in extravagance—not that craftsmen and merchants alone were worthy, but government and teaching made it so.", idiomatic: "Of old craftsmen did not make carved inlay and merchants did not traffic in extravagance—not that craftsmen and merchants alone were worthy, but government and teaching made it so." },
  { zh: "」上以其言為迂闊，不甚寵異也。", literal: "\" The emperor considered his words broad and remote and did not greatly favor or distinguish him.", idiomatic: "\" The emperor considered his words broad and remote and did not greatly favor him." },
  { zh: "吉遂謝病歸。", literal: "Ji thereupon begged leave on grounds of illness and returned home.", idiomatic: "Ji thereupon begged leave on grounds of illness and returned home." },
  { zh: "----3義渠安國至羌中，召先零諸豪三十餘人，以尤桀黠者皆斬之；", literal: "----3 Yiqu Anguo reached the Qiang lands, summoned more than thirty chieftains of the Xianling and the like, and beheaded the most fierce and cunning;", idiomatic: "----3 Yiqu Anguo reached the Qiang lands, summoned more than thirty chieftains of the Xianling, and beheaded the most fierce and cunning;" },
  { zh: "縱兵擊其種人，斬首千餘級。", literal: "he loosed troops to strike their tribesmen and took more than a thousand heads.", idiomatic: "he loosed troops to strike their tribesmen and took more than a thousand heads." },
  { zh: "於是諸降羌及歸義羌侯楊玉等怨怒，無所信嚮，遂劫略小種，背畔犯塞，攻城邑，殺長吏。", literal: "Thereupon the various surrendered Qiang and the Submitted-Righteousness Qiang Marquis Yang Yu and others grew resentful and angry, with nowhere to place their trust, and thereupon plundered lesser tribes, turned their backs, violated the passes, stormed walled towns, and killed chief officials.", idiomatic: "Thereupon the surrendered Qiang and Submitted-Righteousness Qiang Marquis Yang Yu and others grew resentful, with nowhere to place their trust, plundered lesser tribes, rebelled, violated the passes, stormed towns, and killed chief officials." },
  { zh: "安國以騎都尉將騎二千屯備羌；", literal: "Anguo, as Commandant of Cavalry, led two thousand horsemen to garrison in readiness against the Qiang;", idiomatic: "Anguo, as Commandant of Cavalry, led two thousand horsemen to garrison against the Qiang;" },
  { zh: "至浩亹，為虜所擊，失亡車重、兵器甚眾。", literal: "reaching Haowan, he was struck by the barbarians and lost very many wagons, baggage, and weapons.", idiomatic: "reaching Haowan, he was struck by the barbarians and lost very many wagons, baggage, and weapons." },
  { zh: "安國引還，至令居，以聞。", literal: "Anguo led his force back; reaching Lingju, he reported it.", idiomatic: "Anguo led his force back; reaching Lingju, he reported it." },
  { zh: "時趙充國年七十餘，上老之，使丙吉問誰可將者。", literal: "At that time Zhao Chongguo was more than seventy; the emperor considered him old and had Bing Ji ask who could command.", idiomatic: "At that time Zhao Chongguo was more than seventy; the emperor considered him old and had Bing Ji ask who could command." },
  { zh: "充國對曰：「無逾於老臣者矣！", literal: "Chongguo answered: \"None surpasses your old servant!", idiomatic: "Chongguo answered: \"None surpasses your old servant!" },
  { zh: "」上遣問焉，曰：「將軍度羌虜何如？", literal: "\" The emperor sent to question him, saying: \"General, how do you gauge the Qiang barbarians?", idiomatic: "\" The emperor sent to question him: \"General, how do you gauge the Qiang barbarians?" },
  { zh: "當用幾人？", literal: "How many men should be used?", idiomatic: "How many men should be used?" },
  { zh: "」充國曰：「百聞不如一見。", literal: "\" Chongguo said: \"A hundred hearings are not equal to one seeing.", idiomatic: "\" Chongguo said: \"A hundred hearings are not equal to one seeing." },
  { zh: "兵難遙度，臣願馳至金城，圖上方略。", literal: "War is hard to gauge from afar; your servant wishes to gallop to Jincheng and draft stratagems to present above.", idiomatic: "War is hard to gauge from afar; your servant wishes to gallop to Jincheng and draft stratagems for presentation." },
  { zh: "羌戎小夷，逆天背畔，滅亡不久，願陛下以屬老臣，勿以為憂！", literal: "The Qiang and Rong are petty barbarians who oppose Heaven and turn their backs; their destruction will not be long. I wish Your Majesty would entrust them to your old servant and not take worry!", idiomatic: "The Qiang and Rong are petty barbarians who oppose Heaven and rebel; their destruction will not be long. I wish Your Majesty would entrust them to your old servant and not worry!" },
  { zh: "」上笑曰：「諾。", literal: "\" The emperor smiled and said: \"Agreed.", idiomatic: "\" The emperor smiled: \"Agreed." },
  { zh: "」乃大發兵詣金城。", literal: "\" Thereupon he greatly dispatched troops to Jincheng.", idiomatic: "\" Thereupon he greatly dispatched troops to Jincheng." },
  { zh: "夏，四月，遣充國將之，以擊西羌。", literal: "In summer, the fourth month, he dispatched Chongguo to command them in striking the Western Qiang.", idiomatic: "In summer, the fourth month, he dispatched Chongguo to command them against the Western Qiang." },
  { zh: "----4六月，有星孛於東方。", literal: "----4 In the sixth month, a broom star appeared in the east.", idiomatic: "----4 In the sixth month, a broom star appeared in the east." },
  { zh: "----5趙充國至金城，須兵滿萬騎，欲渡河，恐為虜所遮，即夜遣三校銜枚先渡，渡，輒營陳；", literal: "----5 Zhao Chongguo reached Jincheng, waited until troops reached ten thousand horse, wished to cross the river, and feared the barbarians would intercept him; that very night he sent three colonels with gagged mouths to cross first—once across, they at once pitched formations;", idiomatic: "----5 Zhao Chongguo reached Jincheng, waited until troops reached ten thousand horse, wished to cross the river, and feared the barbarians would intercept him; that night he sent three colonels with gagged mouths to cross first—once across, they at once pitched formations;" },
  { zh: "會明畢，遂以次盡渡。", literal: "when dawn was fully come, the rest crossed in order.", idiomatic: "when dawn came, the rest crossed in order." },
  { zh: "虜數十百騎來，出入軍傍，充國曰：「吾士馬新倦，不可馳逐，此皆驍騎難制，又恐其為誘兵也。", literal: "Several tens or hundreds of barbarian horsemen came, passing in and out beside the army. Chongguo said: \"Our men and horses are newly weary and cannot be driven in chase; these are all fierce horsemen hard to control, and I also fear they may be decoy troops.", idiomatic: "Several tens or hundreds of barbarian horsemen came, passing in and out beside the army. Chongguo said: \"Our men and horses are newly weary and cannot be driven in chase; these are fierce horsemen hard to control, and I fear they may be decoys." },
  { zh: "擊虜以殄滅為期，小利不足貪！", literal: "Striking barbarians takes their total destruction as the term—small gains are not worth coveting!", idiomatic: "Striking barbarians takes their total destruction as the goal—small gains are not worth coveting!" },
  { zh: "」令軍勿擊。", literal: "\" He ordered the army not to strike.", idiomatic: "\" He ordered the army not to strike." },
  { zh: "遣騎候四望陿中無虜，夜，引兵上至落都，召諸校司馬謂曰：「吾知羌虜不能為兵矣！", literal: "He sent horsemen to scout the Four-View Pass and found no barbarians; by night he led troops up to Luodu, summoned the various colonels and majors, and said: \"I know the Qiang barbarians cannot make war!", idiomatic: "He sent horsemen to scout the Four-View Pass and found no barbarians; by night he led troops up to Luodu, summoned the colonels and majors, and said: \"I know the Qiang barbarians cannot make war!" },
  { zh: "使虜發數千人守杜四望陿中，兵豈得入哉！", literal: "Had the barbarians sent several thousand men to hold and block the Four-View Pass, how could our troops have entered!", idiomatic: "Had the barbarians sent several thousand men to hold the Four-View Pass, how could our troops have entered!" },
  { zh: "充國常以遠斥候為務，行必為戰備，止必堅營壁，尤能持重，愛士卒，先計而後戰。", literal: "Chongguo always made distant scouting his task; on the march he invariably prepared for battle, at halt he invariably fortified ramparts and walls; he was especially able to hold weight, loved his soldiers, and planned before fighting.", idiomatic: "Chongguo always made distant scouting his task; on the march he prepared for battle, at halt he fortified ramparts; he especially held weight, loved his soldiers, and planned before fighting." },
  { zh: "遂西至西部都尉府，日饗軍士，士皆欲為用。", literal: "He then marched west to the Western Division Commandant's headquarters, daily feasting the soldiers; the soldiers all wished to be used by him.", idiomatic: "He then marched west to the Western Division Commandant's headquarters, daily feasting the soldiers; the soldiers all wished to serve him." },
  { zh: "虜數挑戰，充國堅守。", literal: "The barbarians repeatedly challenged battle; Chongguo held firm.", idiomatic: "The barbarians repeatedly challenged battle; Chongguo held firm." },
  { zh: "捕得生口，言羌豪相數責曰：「語汝無反，今天子遣趙將軍來，年八九十矣，善為兵；", literal: "Captives taken alive said the Qiang chieftains reproached one another, saying: \"We told you not to rebel; now the Son of Heaven has sent General Zhao—he is eighty or ninety and skilled at war;", idiomatic: "Captives said the Qiang chieftains reproached one another: \"We told you not to rebel; now the Son of Heaven has sent General Zhao—he is eighty or ninety and skilled at war;" },
  { zh: "今請欲壹鬥而死，可得邪！", literal: "now if you wish to fight one decisive battle and die, can you have it!", idiomatic: "now if you wish one decisive battle and death, can you have it!" },
  { zh: "」初，罕、幵豪靡當兒使弟雕庫來告都尉曰：「先零欲反。", literal: "\" Earlier the chieftain Midang'er of the Han and Qian tribes sent his younger brother Diaoku to tell the Commandant: \"The Xianling wish to rebel.", idiomatic: "\" Earlier chieftain Midang'er of the Han and Qian tribes sent his younger brother Diaoku to tell the Commandant: \"The Xianling wish to rebel." },
  { zh: "」後數日，果反。", literal: "\" Several days later they indeed rebelled.", idiomatic: "\" Several days later they indeed rebelled." },
  { zh: "雕庫種人頗在先零中，都尉即留雕庫為質。", literal: "Many of Diaoku's tribesmen were among the Xianling; the Commandant thereupon detained Diaoku as hostage.", idiomatic: "Many of Diaoku's tribesmen were among the Xianling; the Commandant thereupon detained Diaoku as hostage." },
  { zh: "充國以為無罪，乃遣歸告種豪：「大兵誅有罪者，明白自別，毋取並滅。", literal: "Chongguo considered him guiltless and thereupon sent him back to tell the tribal chieftains: \"The great army punishes the guilty; make plain distinctions among yourselves—do not bring total destruction upon all.", idiomatic: "Chongguo considered him guiltless and sent him back to tell the tribal chieftains: \"The great army punishes the guilty; distinguish yourselves clearly—do not bring total destruction upon all." },
  { zh: "天子告諸羌人：犯法者能相捕斬，除罪，仍以功大小賜錢有差；", literal: "The Son of Heaven announced to the various Qiang: those who could mutually capture and behead lawbreakers would be cleared of guilt, and still according to the size of merit money would be bestowed in graded amounts;", idiomatic: "The emperor announced to the Qiang: whoever could capture and behead offenders would be cleared of guilt, and would still receive money graded by the size of his merit;" },
  { zh: "又以其所捕妻子、財物盡與之。", literal: "furthermore their captured wives and children and goods and property would all be given to them.", idiomatic: "and the wives, children, and goods they captured would all be given to them." },
  { zh: "」充國計欲以威信招降罕、幵及劫略者，解散虜謀，徼其疲劇，乃擊之。", literal: "\" Chongguo planned to use prestige and trust to summon surrender from the Han, Qian, and plunderers, disperse the barbarians' plotting, wait for their exhaustion, and then strike them.", idiomatic: "\" Chongguo planned to win over the Han, Qian, and plunderers by prestige and good faith, break up their conspiracy, wait until they were worn down, and then attack." },
  { zh: "時上已發內郡兵屯邊者合六萬人矣。", literal: "At that time the emperor had already mobilized troops from the inner commanderies stationed on the border, totaling sixty thousand men.", idiomatic: "By then the emperor had mobilized sixty thousand troops from the inner commanderies to garrison the frontier." },
  { zh: "酒泉太守辛武賢奏言：「郡兵皆屯備南山，北邊空虛，勢不可久。", literal: "Governor of Jiuquan Xin Wuxian memorialized, saying: \"The commandery troops are all stationed guarding the southern mountains; the northern border is empty and the situation cannot last long.", idiomatic: "Governor of Jiuquan Xin Wuxian memorialized, \"The commandery troops are all posted guarding the southern mountains; the northern border is empty and this cannot last." },
  { zh: "若至秋冬乃進兵，此虜在境外之冊。", literal: "If we advance troops only when autumn and winter arrive, this is the barbarians' plan beyond the border.", idiomatic: "If we wait until autumn and winter to advance, that is the barbarians' plan for staying beyond the border." },
  { zh: "今虜朝夕為寇，土地寒苦，漢馬不耐冬，不如以七月上旬繼三十日糧，分兵出張掖、酒泉，合擊罕、幵在鮮水上者。", literal: "Now the barbarians raid morning and evening; the land is cold and bitter; Han horses cannot endure winter—better to carry thirty days' grain in the first ten days of the seventh month, divide troops out from Zhangye and Jiuquan, and jointly strike the Han and Qian on the Xianshui.", idiomatic: "Now the barbarians raid day and night; the land is cold and harsh and Han horses cannot endure winter. Better to carry thirty days' grain in the first ten days of the seventh month, divide forces from Zhangye and Jiuquan, and jointly strike the Han and Qian on the Xianshui." },
  { zh: "雖不能盡誅，但奪其畜產，虜其妻子，復引兵還。", literal: "Though we cannot exterminate them all, we need only seize their livestock, capture their wives and children, and lead the troops back again.", idiomatic: "Though we cannot exterminate them all, we need only seize their livestock, capture their wives and children, and withdraw." },
  { zh: "冬復擊之，大兵仍出，虜必震壞。", literal: "In winter strike them again; great armies still go forth—the barbarians will surely be shaken and broken.", idiomatic: "Strike again in winter with great armies still in the field, and the barbarians will surely be shaken to ruin." },
  { zh: "天子下其書充國，令議之。", literal: "The Son of Heaven sent down his memorial to Chongguo and ordered discussion of it.", idiomatic: "The emperor forwarded the memorial to Chongguo for discussion." },
  { zh: "充國以為：「一馬自負三十日食，為米二斛四斗，麥八斛，又有衣裝、兵器，難以追逐。", literal: "Chongguo held: \"One horse bearing thirty days' food amounts to two hu four dou of rice, eight hu of wheat, and besides clothing, gear, and weapons—hard to pursue in chase.", idiomatic: "Chongguo replied, \"One horse carrying thirty days' rations means two hu four dou of rice and eight hu of wheat, plus clothing, gear, and weapons—too heavy to pursue effectively." },
  { zh: "虜必商軍進退，稍引去，逐水草，入山林。", literal: "The barbarians will surely deliberate on the army's advance and retreat, gradually draw away, follow water and grass, and enter mountains and forests.", idiomatic: "The barbarians will watch our movements, gradually withdraw, follow pasture and water, and slip into the mountains." },
  { zh: "隨而深入，虜即據前險，守後厄，以絕糧道，必有傷危之憂，為夷狄笑，千載不可復。", literal: "If we follow and go deep in, the barbarians will then hold the forward defiles, guard the rear narrows, and cut the grain route—we will surely have worry of injury and peril, be laughed at by the Yi and Di, and for a thousand years cannot recover.", idiomatic: "If we follow deep inside, they will hold the forward passes, guard the rear narrows, and cut our supply line. We risk injury and ruin, become a laughingstock to the barbarians, and suffer disgrace for ages." },
  { zh: "而武賢以為可奪其畜產，虜其妻子，此殆空言，非至計也。", literal: "Yet Wuxian thought one could seize their livestock and capture their wives and children—this is nearly empty talk, not the supreme plan.", idiomatic: "Yet Wuxian thinks we can seize their livestock and capture their families—that is empty talk, not the best plan." },
  { zh: "先零首為畔逆，他種劫略，故臣愚冊，欲捐罕、幵闇昧之過，隱而勿章，先行先零之誅以震動之，宜悔過反善，因赦其罪，選擇良吏知其俗者，拊循和輯。", literal: "Xianling first led rebellion; other tribes plundered—therefore your servant's foolish plan wishes to overlook the Han and Qian's obscure faults, conceal and not expose them, first carry out punishment of Xianling to shake them, that they ought to repent, turn to goodness, and thereby pardon their crimes, select good officials who know their customs, and comfort and harmonize them.", idiomatic: "Xianling led the rebellion and other tribes plundered. Your servant's plan is to overlook the Han and Qian's lesser faults, conceal rather than expose them, first punish Xianling to shake them into repentance, pardon their crimes, and send good officials who know their customs to comfort and reconcile them." },
  { zh: "此全師保勝安邊之冊。", literal: "This is the plan to preserve the army, secure victory, and settle the border.", idiomatic: "That is the plan to preserve the army, secure victory, and settle the border." },
  { zh: "天子下其書，公卿議者-{咸}-以為「先零兵盛而負罕、幵之助。", literal: "The Son of Heaven sent down his memorial; the discussing ministers and grandees all held that \"Xianling's troops are strong and rely on Han and Qian aid.", idiomatic: "The emperor forwarded the memorial; the discussing ministers all held that \"Xianling's troops are strong and rely on aid from the Han and Qian." },
  { zh: "不先破罕、幵，則先零未可圖也。", literal: "If we do not first break the Han and Qian, then Xianling cannot be taken in hand.", idiomatic: "Unless we first break the Han and Qian, Xianling cannot be dealt with." },
  { zh: "」上乃拜侍中許壽為強弩將軍，即拜酒泉太守武賢為破羌將軍，賜璽書嘉納其冊。", literal: "\" The emperor thereupon appointed Palace Attendant Xu Shou as Strong Crossbow General, immediately appointed Jiuquan Governor Wuxian as Break-Qiang General, and bestowed an imperial-seal letter praising and accepting his plan.", idiomatic: "\" The emperor appointed Palace Attendant Xu Shou as Strong Crossbow General, immediately made Jiuquan Governor Wuxian Break-Qiang General, and sent an imperial letter praising and accepting his plan." },
  { zh: "以書敕讓充國曰：「今轉輸並起，百姓煩擾，將軍將萬餘之眾，不早及秋共水草之利，爭其畜食，欲至冬，虜皆當畜食，多臧匿山中，依險阻，將軍士寒，手足皸瘃，寧有利哉！", literal: "With a letter he reprimanded Chongguo, saying: \"Now transport levies rise together and the people are troubled; the general commands more than ten thousand men yet does not early reach autumn to share the benefit of water and grass and contend for their stored fodder. If you wait until winter, the barbarians will all store fodder and hide much in the mountains, relying on peril and obstruction; the general's soldiers will be cold, hands and feet chapped and frostbitten—can there be advantage!", idiomatic: "He sent a letter reprimanding Chongguo: \"Transport levies are piling up and the people are troubled. You command more than ten thousand men yet will not seize autumn's pasture and fodder. Wait until winter and the barbarians will have stored fodder and hidden in the mountains behind difficult ground. Your soldiers will freeze, hands and feet chapped and frostbitten—where is the advantage?" },
  { zh: "將軍不念中國之費，欲以歲數而勝敵，將軍誰不樂此者！", literal: "The general does not consider the Middle Kingdom's expense yet wishes to overcome the enemy over years—who among the generals would not delight in this!", idiomatic: "You ignore the empire's expense and wish to defeat the enemy over years—who would not prefer that!" },
  { zh: "今詔破羌將軍武賢等將兵，以七月擊罕羌。", literal: "Now we decree that Break-Qiang General Wuxian and others shall lead troops to strike the Han Qiang in the seventh month.", idiomatic: "We now decree that Break-Qiang General Wuxian and others shall lead troops to strike the Han Qiang in the seventh month." },
  { zh: "將軍其引兵並進，勿復有疑！", literal: "The general should lead troops and advance together—do not again have doubts!", idiomatic: "Advance together with them and harbor no more doubts!" },
  { zh: "充國上書曰：「陛下前幸賜書，欲使人諭罕，以大軍當至，漢不誅罕，以解其謀。", literal: "Chongguo submitted a memorial, saying: \"Your Majesty before graciously bestowed a letter wishing to have someone instruct the Han tribe that great armies were about to arrive, that Han would not punish the Han tribe, to dissolve their plotting.", idiomatic: "Chongguo submitted a memorial: \"Your Majesty previously sent a letter wishing to tell the Han tribe that great armies were coming and that Han would not punish them, to break up their plotting." },
  { zh: "臣故遣幵豪雕庫宣天子至德；", literal: "Your servant therefore sent the Qian chieftain Diaoku to proclaim the Son of Heaven's utmost virtue;", idiomatic: "Your servant therefore sent the Qian chieftain Diaoku to proclaim the emperor's utmost virtue;" },
  { zh: "罕、幵之屬皆聞知明詔。", literal: "the Han, Qian, and their kind all heard and knew the clear edict.", idiomatic: "the Han, Qian, and their followers all heard the clear edict." },
  { zh: "今先零羌楊玉阻石山木，候便為寇，罕羌未有所犯，乃置先零，先擊罕，釋有罪，誅無辜，起壹難，就兩害，誠非陛下本計也。", literal: "Now the Xianling Qiang Yang Yu blocks stone mountains and timber, watches for opportunity and raids; the Han Qiang have committed no offense—yet you set aside Xianling and first strike the Han, releasing the guilty and executing the innocent, raising one difficulty and incurring two harms—this truly is not Your Majesty's original plan.", idiomatic: "Now Xianling leader Yang Yu holds the mountain passes and raids at opportunity, while the Han Qiang have done no wrong. Yet you set aside Xianling and strike the Han first, sparing the guilty and punishing the innocent, raising one trouble and incurring two harms—this is truly not Your Majesty's original plan." },
  { zh: "臣聞兵法：『攻不足者守有餘。", literal: "Your servant has heard in the art of war: 'Attack where there is insufficiency; defend where there is surplus.", idiomatic: "Your servant has heard in the art of war, 'Attack where the enemy is weak; defend where you are strong." },
  { zh: "』又曰：『善戰者致人，不致於人。", literal: "' It also says: 'The skilled in battle bring the enemy to them, and are not brought to by the enemy.", idiomatic: "' It also says, 'The skilled fighter brings the enemy to him and is not brought to by the enemy." },
  { zh: "』今罕羌欲為敦煌、酒泉寇，宜飭兵馬，練戰士，以須其至。", literal: "' Now the Han Qiang wish to raid Dunhuang and Jiuquan—one ought to order troops and horses, drill warriors, and await their coming.", idiomatic: "' Now the Han Qiang wish to raid Dunhuang and Jiuquan. Order troops and horses, drill the men, and await their coming." },
  { zh: "坐得致敵之術，以逸擊勞，取勝之道也。", literal: "Sitting, one obtains the method of bringing the enemy—striking the rested against the weary is the way to gain victory.", idiomatic: "That way we obtain the method of bringing the enemy to us—striking the rested against the weary is the way to victory." },
  { zh: "今恐二郡兵少，不足以守，而發之行攻，釋致虜之術而從為虜所致之道，臣愚以為不便。", literal: "Now I fear the two commanderies' troops are few and insufficient to defend, yet you dispatch them on offensive marches, abandoning the method of bringing the barbarians and instead following the way of being brought to by the barbarians—your servant in folly holds this inconvenient.", idiomatic: "Now I fear the two commanderies have too few troops to defend, yet you send them on the attack, abandoning the method of bringing the enemy to us and following instead the way of being brought to by them—your servant thinks this unwise." },
  { zh: "先零羌虜欲為背畔，故與罕、幵解仇結約，然其私心不能無恐漢兵而罕、幵背之也。", literal: "The Xianling Qiang barbarians wish to rebel, therefore they made peace with the Han and Qian and formed covenants; yet in their private hearts they cannot but fear Han troops while the Han and Qian turn on them.", idiomatic: "The Xianling Qiang wish to rebel and therefore made peace with the Han and Qian and formed alliances, yet in their hearts they cannot but fear that Han troops will come while the Han and Qian turn on them." },
  { zh: "臣愚以為其計常欲先赴罕、幵之急以堅其約。", literal: "Your servant in folly holds that their plan constantly wishes first to rush to the Han and Qian's urgency to firm their covenant.", idiomatic: "Your servant thinks their plan is always to rush first to aid the Han and Qian in order to cement the alliance." },
  { zh: "先擊罕羌，先零必助之。", literal: "Strike the Han Qiang first and Xianling will surely aid them.", idiomatic: "Strike the Han Qiang first and Xianling will surely aid them." },
  { zh: "今虜馬肥、糧食方饒，擊之恐不能傷害，適使先零得施德於罕羌，堅其約，合其黨。", literal: "Now the barbarians' horses are fat and grain provisions abundant; strike them and I fear we cannot harm them—only fitting that Xianling gain merit with the Han Qiang, firm their covenant, and unite their faction.", idiomatic: "Now their horses are fat and their grain abundant. Attack and we may fail to harm them, only letting Xianling win favor with the Han Qiang, cement the alliance, and unite their faction." },
  { zh: "虜交堅黨，合精兵二萬餘人，迫脅諸小種，附著者稍眾，莫須之屬不輕得離也。", literal: "The barbarians' ties firm, their faction united, they combine crack troops of more than twenty thousand men, coerce the various lesser tribes, and those attaching themselves gradually grow numerous—the Mo-xu kind cannot lightly be separated.", idiomatic: "With their ties firm and faction united, they will combine more than twenty thousand crack troops, coerce the lesser tribes, and those joining them will grow in number. The Mo-xu tribes will not easily be separated." },
  { zh: "如是，虜兵浸多，誅之用力數倍。", literal: "If so, barbarian troops gradually increase and punishing them will cost several times the effort.", idiomatic: "Then barbarian forces will grow and punishing them will cost several times the effort." },
  { zh: "臣恐國家憂累，由十年數，不二三歲而已。", literal: "Your servant fears the state's troubles and burdens may run to a decade's count, not merely two or three years.", idiomatic: "Your servant fears the state's troubles may last a decade, not merely two or three years." },
  { zh: "於臣之計，先誅先零已，則罕、幵之屬不煩兵而服矣。", literal: "In your servant's plan, first execute Xianling and done, then the Han, Qian, and their kind will submit without troubling the army.", idiomatic: "In your servant's plan, punish Xianling first and the Han, Qian, and their followers will submit without need of troops." },
  { zh: "先零已誅而罕、幵不服，涉正月擊之，得計之理，又其時也。", literal: "If Xianling is already executed yet the Han and Qian do not submit, strike them crossing into the first month—that is the principle of gaining the plan, and again its season.", idiomatic: "If Xianling is punished yet the Han and Qian do not submit, strike them when the first month comes—that is sound strategy and the right season." },
  { zh: "以今進兵，誠不見其利。", literal: "To advance troops now—I truly do not see its advantage.", idiomatic: "To advance troops now—I see no advantage." },
  { zh: "戊申，充國上奏。", literal: "Day wushen: Chongguo submitted a memorial.", idiomatic: "On day wushen, Chongguo submitted a memorial." },
  { zh: "秋，七月，甲寅，璽書報，從充國計焉。", literal: "Autumn, seventh month, day jiayin: an imperial-seal letter replied, following Chongguo's plan.", idiomatic: "In autumn, the seventh month, on day jiayin, an imperial letter replied, adopting Chongguo's plan." },
  { zh: "充國乃引兵至先零在所。", literal: "Chongguo thereupon led troops to where Xianling was.", idiomatic: "Chongguo then led his troops to where Xianling was encamped." },
  { zh: "虜久屯聚，懈馳，望見大軍，棄車重，欲渡湟水，道厄狹，充國徐行驅之。", literal: "The barbarians had long encamped and gathered, slack and lax; seeing the great army, they abandoned baggage and wagons and wished to cross the Huangshui—the road was narrow and perilous, and Chongguo advanced slowly driving them.", idiomatic: "The barbarians had long been encamped and grown slack. Seeing the great army, they abandoned baggage and tried to cross the Huang River on a narrow, difficult road. Chongguo advanced slowly, driving them on." },
  { zh: "或曰：「逐利行遲。", literal: "Someone said: \"In pursuit of gain, marching is slow.", idiomatic: "Someone said, \"In pursuit of gain you march too slowly." },
  { zh: "」充國曰：「此窮寇，不可迫也。", literal: "\" Chongguo said: \"These are cornered bandits—they cannot be pressed.", idiomatic: "\" Chongguo said, \"These are cornered bandits and cannot be pressed." },
  { zh: "緩之則走不顧，急之則還致死。", literal: "If eased they will flee without looking back; if pressed they will turn and fight to the death.", idiomatic: "If eased they will flee without looking back; if pressed they will turn and fight to the death." },
  { zh: "」諸校皆曰：「善。", literal: "\" The various commandants all said: \"Good.", idiomatic: "\" The commandants all said, \"Good." },
  { zh: "」虜赴水溺死者數百。", literal: "\" The barbarians rushing to the water drowned—several hundred dead.", idiomatic: "\" Several hundred barbarians drowned rushing into the water." },
  { zh: "降及斬首五百餘人。", literal: "Those who surrendered and heads cut numbered more than five hundred.", idiomatic: "More than five hundred surrendered or were beheaded." },
  { zh: "虜馬、牛、羊十萬餘頭，車四千餘兩。", literal: "Barbarian horses, cattle, and sheep numbered more than one hundred thousand head; wagons more than four thousand.", idiomatic: "They took more than one hundred thousand barbarian horses, cattle, and sheep and more than four thousand wagons." },
  { zh: "兵至罕地，令軍毋燔聚落、芻牧田中。", literal: "When the army reached Han territory, he ordered the army not to burn settlements or hay in pasture and farming fields.", idiomatic: "When the army reached Han territory, he ordered that settlements and pasture hay not be burned." },
  { zh: "罕羌聞之，喜曰：「漢果不擊我矣！", literal: "The Han Qiang heard it and rejoiced, saying: \"Han indeed will not strike us!", idiomatic: "The Han Qiang heard this and rejoiced, \"Han indeed will not attack us!" },
  { zh: "」豪靡忘使人來言：「願得還復故地。", literal: "\" Chieftain Mi Wang sent a man to say: \"We wish to be able to return and recover our former lands.", idiomatic: "\" Chieftain Mi Wang sent a messenger saying, \"We wish to return to our former lands." },
  { zh: "」充國以聞，未報。", literal: "\" Chongguo reported it upward; no reply yet.", idiomatic: "\" Chongguo reported this; no reply came." },
  { zh: "靡忘來自歸，充國賜飲食，遣還諭種人。", literal: "Mi Wang came in person to surrender; Chongguo bestowed food and drink and sent him back to instruct his tribesmen.", idiomatic: "Mi Wang came to surrender in person. Chongguo gave him food and drink and sent him back to instruct his people." },
  { zh: "護軍以下皆爭之曰：「此反虜，不可擅遣！", literal: "The Protector of the Army and those below all disputed it, saying: \"This is a rebel barbarian—he cannot be sent off on your own authority!", idiomatic: "The Protector of the Army and those below all objected, \"This rebel cannot be sent off on your own authority!" },
  { zh: "」充國曰：「諸君但欲便文自營，非為公家忠計也！", literal: "\" Chongguo said: \"You gentlemen only wish convenient paperwork for your own benefit—not loyal planning for the public house!", idiomatic: "\" Chongguo said, \"You gentlemen only want convenient paperwork for yourselves, not loyal planning for the state!" },
  { zh: "」語未卒，璽書報，令靡忘以贖論。", literal: "\" Before the words ended, an imperial-seal letter replied, ordering Mi Wang judged by ransom.", idiomatic: "\" Before he finished speaking, an imperial letter arrived ordering Mi Wang judged by ransom." },
  { zh: "後罕竟不煩兵而下。", literal: "Later the Han in the end submitted without troubling the army.", idiomatic: "Later the Han submitted without need of troops." },
  { zh: "上詔破羌、強弩將軍詣屯所，以十二月與充國合，進擊先零。", literal: "The emperor decreed the Break-Qiang and Strong Crossbow generals to proceed to the garrison place and in the twelfth month join Chongguo and advance to strike Xianling.", idiomatic: "The emperor decreed the Break-Qiang and Strong Crossbow generals to the garrison and to join Chongguo in the twelfth month to attack Xianling." },
  { zh: "時羌降者萬餘人矣，充國度其必壞，欲罷騎兵，屯田以待其敝。", literal: "At that time Qiang who had surrendered numbered more than ten thousand; Chongguo estimated they would surely break and wished to dismiss the cavalry and garrison-farm awaiting their exhaustion.", idiomatic: "By then more than ten thousand Qiang had surrendered. Chongguo judged they would surely collapse and wished to dismiss the cavalry and farm garrison land awaiting their exhaustion." },
  { zh: "作奏未上，會得進兵璽書，充國子中郎將卬懼，使客諫充國曰：「誠令兵出，破軍殺將，以傾國家，將軍守之可也。", literal: "He drafted a memorial but had not submitted it when he received an imperial-seal letter to advance troops; Chongguo's son Palace Gentleman Ang in fear had a client admonish Chongguo, saying: \"If troops truly go forth, the army is broken and the general killed, overturning the state—the general may hold to that.", idiomatic: "He drafted a memorial but had not submitted it when an imperial letter arrived ordering advance. Chongguo's son, Palace Gentleman Ang, in fear had a client admonish him: \"If troops go forth and the army is broken and the general killed, overturning the state, you may hold to that." },
  { zh: "即利與病，又何足爭？", literal: "If there is gain or illness, what is worth contending over?", idiomatic: "Whether there is gain or blame, what is worth contending over?" },
  { zh: "一旦不合上意，遣繡衣來責將軍，將軍之身不能自保，何國家之安！", literal: "Once it does not accord with the emperor's intent, he will send the embroidered-gown messenger to reproach the general—the general's person cannot preserve itself—what of the state's security!", idiomatic: "Once you displease the emperor, he will send the embroidered-gown messenger to reproach you. You cannot preserve yourself—what of the state's security!" },
  { zh: "」充國漢曰：「是何言之不忠也！", literal: "\" Chongguo laughed and said: \"What disloyal words are these!", idiomatic: "\" Chongguo laughed and said, \"What disloyal words are these!" },
  { zh: "本用吾言，羌虜得至是邪！", literal: "Had they originally used my words, would the Qiang barbarians have reached this!", idiomatic: "Had they originally followed my counsel, would the Qiang have reached this point!" },
  { zh: "往者舉可先行羌者，吾舉辛武賢；", literal: "In the past when they raised who could first act against the Qiang, I raised Xin Wuxian;", idiomatic: "When they asked who could act first against the Qiang, I named Xin Wuxian;" },
  { zh: "丞相御史復白遣義渠安國，竟沮敗羌。", literal: "the chancellor and imperial censor again reported and sent Yiqu Anguo, who in the end obstructed and ruined the Qiang campaign.", idiomatic: "the chancellor and censor reported again and sent Yiqu Anguo, who in the end obstructed and ruined the campaign." },
  { zh: "金城、湟中谷斛八錢，吾謂耿中丞：『糴三百萬斛穀，羌人不敢動矣！", literal: "In Jincheng and Huangzhong grain was eight cash per hu; I told Supervisor of the Palace Gentlemen Geng: 'Buy three million hu of grain and the Qiang will not dare move!", idiomatic: "In Jincheng and Huangzhong grain was eight cash per hu. I told Supervisor Geng, 'Buy three million hu of grain and the Qiang will not dare move!" },
  { zh: "』耿中丞請糴百萬斛，乃得四十萬斛耳；", literal: "' Supervisor Geng requested buying one million hu and obtained only four hundred thousand hu;", idiomatic: "' Geng requested one million hu and obtained only four hundred thousand;" },
  { zh: "義渠再使，且費其半。", literal: "Yiqu was sent again and moreover spent half of it.", idiomatic: "Yiqu was sent again and moreover spent half of it." },
  { zh: "失此二冊，羌人致敢為逆。", literal: "Losing these two plans, the Qiang came to dare rebellion.", idiomatic: "Losing these two plans, the Qiang came to dare rebellion." },
  { zh: "失之毫釐，差以千里，是既然矣。", literal: "Missing by a hair's breadth, the error stretches a thousand li—this is already clear.", idiomatic: "Missing by a hair, the error stretches a thousand li—that is already clear." },
  { zh: "今兵久不決，四夷卒有動搖，相因而起，雖有知者不能善其後，羌獨足憂邪？", literal: "Now troops long unresolved—of the four Yi, in the end some may stir and rise in succession; even if there were wise men they could not make good the aftermath—is the Qiang alone enough to worry about?", idiomatic: "Now the campaign drags on unresolved. The four barbarians may stir and rise in succession. Even the wise could not repair the aftermath afterward. Is the Qiang alone worth worrying about?" },
  { zh: "吾固以死守之，明主可為忠言。", literal: "I firmly hold to death in defending it—a clear ruler may receive loyal words.", idiomatic: "I will defend it to the death. A clear ruler may receive loyal counsel." },
  { zh: "遂上屯田奏曰：「臣所將吏士、馬牛食所用糧穀、茭稿，調度甚廣，難久不解，徭役不息，恐生它變，為明主憂，誠非素定廟勝之冊。", literal: "Thereupon he submitted a garrison-farming memorial, saying: \"The grain and fodder used by the officers, soldiers, horses, and cattle your servant leads require very broad allocation; it is hard to resolve for long and corvée labor does not cease—I fear other changes will arise and trouble a clear ruler; this truly is not the plan settled beforehand in the temple for victory.", idiomatic: "Thereupon he submitted a garrison-farming memorial: \"The grain and fodder for the officers, soldiers, horses, and cattle I lead require vast supply. The campaign cannot drag on and corvée labor never ceases. I fear other troubles will arise to trouble a clear ruler. This is truly not the plan settled in the temple for victory." },
  { zh: "且羌易以計破，難用兵碎也，故臣愚心以為擊之不便！", literal: "Moreover the Qiang are easy to break by stratagem and hard to smash by arms—therefore your servant's foolish heart holds that striking them is inconvenient!", idiomatic: "Moreover the Qiang are easy to defeat by strategy and hard to smash by force. Your servant's foolish heart holds that attacking is unwise!" },
  { zh: "計度臨羌東至浩亹，羌虜故田及公田，民所未墾，可二千頃以上，其間郵亭多壞敗者。", literal: "Estimating from east of Linqiang to Haowan, former Qiang barbarian fields and public fields the people have not yet opened—more than two thousand qing—and among them many postal stations are ruined.", idiomatic: "From east of Linqiang to Haowan there are more than two thousand qing of former Qiang fields and public land the people have not yet opened, and many postal stations along the way are ruined." },
  { zh: "臣前部士入山，伐林木六萬餘枚，在水次。", literal: "Your servant earlier deployed soldiers into the mountains and felled more than sixty thousand timbers, placed at the water's edge.", idiomatic: "Your servant earlier sent men into the mountains and felled more than sixty thousand timbers, stacked at the water's edge." },
  { zh: "臣願罷騎兵，留步兵萬二百八十一人，分屯要害處，冰解漕下，繕鄉亭，浚溝渠，治湟陿以西道橋七十所，令可至鮮水左右。", literal: "Your servant wishes to dismiss the cavalry and leave ten thousand two hundred eighty-one foot soldiers, divided to garrison key places; when ice breaks, transport down by canal, repair village stations, dredge ditches and canals, repair more than seventy road bridges west of Huangxia, making it possible to reach both sides of the Xianshui.", idiomatic: "Your servant wishes to dismiss the cavalry and leave 10,281 foot soldiers posted at key points. When the ice breaks, float supplies downriver, repair stations, dredge canals, and build more than seventy bridges west of Huang Gorge so the road reaches both sides of the Xianshui." },
  { zh: "田事出，賦人三十畝；", literal: "When farming work emerges, assign each man thirty mu;", idiomatic: "When farming begins, assign each man thirty mu;" },
  { zh: "至四月草生，發郡騎及屬國胡騎各千，就草為田者遊兵，以充入金城郡，益積畜，省大費。", literal: "when the fourth month grass grows, dispatch commandery cavalry and Dependent-State Hu cavalry one thousand each as roaming troops for those farming by the grass, to fill into Jincheng commandery, increase stored provisions, and save great expense.", idiomatic: "when grass grows in the fourth month, dispatch one thousand commandery cavalry and one thousand Dependent-State Hu cavalry as roaming troops for the farmers, to reinforce Jincheng, increase stores, and save great expense." },
  { zh: "今大司農所轉穀至者，足支萬人一歲食，謹上田處及器用簿。", literal: "Now grain the Grand Minister of Agriculture transports and that has arrived is sufficient to supply ten thousand men for one year's food—your servant respectfully submits the farming places and tools register.", idiomatic: "Grain the Grand Minister of Agriculture has transported already suffices for ten thousand men for one year. Your servant respectfully submits the farming sites and equipment register." },
  { zh: "上報曰：「即如將軍之計，虜當何時伏誅？", literal: "The emperor replied: \"If we immediately follow the general's plan, when should the barbarians submit to execution?", idiomatic: "The emperor replied, \"If we follow your plan at once, when will the barbarians submit to punishment?" },
  { zh: "兵當何時得決？", literal: "When should the troops be resolved?", idiomatic: "When will the campaign be settled?" },
  { zh: "孰計其便，復奏。", literal: "Which plan is convenient—memorialize again.", idiomatic: "Calculate which is better and memorialize again." },
  { zh: "充國上狀曰：「臣聞帝王之兵，以全取勝，是以貴謀而賤戰。", literal: "Chongguo submitted a report, saying: \"Your servant has heard that an emperor or king's troops take victory through preserving the whole—therefore they esteem stratagem and slight battle.", idiomatic: "Chongguo submitted a report: \"Your servant has heard that a true ruler's army wins by preserving wholeness, and therefore esteems strategy and slightes battle." },
  { zh: "『百戰而百勝，非善之善者也，故先為不可勝以待敵之可勝。", literal: "'A hundred battles and a hundred victories is not the good among the good; therefore first make yourself unbeatable and await the enemy becoming beatable.", idiomatic: "'A hundred victories in a hundred battles is not the highest excellence. First make yourself unbeatable and await the moment the enemy can be beaten." },
  { zh: "』蠻夷習俗雖殊於禮義之國，然其欲避害就利，愛親戚，畏死亡，一也。", literal: "' The barbarians' customs though differ from states of ritual and righteousness, yet their wish to flee harm and seek profit, love kin, and fear death are one.", idiomatic: "' Though barbarian customs differ from civilized states, their wish to flee harm and seek profit, love kin, and fear death are the same." },
  { zh: "今虜亡其美地薦草，愁於寄托，遠遁，骨肉心離，人有畔志。", literal: "Now the barbarians have lost their fine lands and lush grass, are anxious in lodging, flee far, kin hearts divided, and men have thoughts of rebellion.", idiomatic: "Now the barbarians have lost their fine lands and lush pasture, are anxious in exile, flee far off, families are divided at heart, and men harbor thoughts of defection." },
  { zh: "而明主班師罷兵，萬人留田，順天時，因地利，以待可勝之虜，雖未即伏辜，兵決可期月而望，羌虜瓦解，前後降者萬七百餘人，及受言去者凡七十輩，此坐支解羌虜之具也。", literal: "Yet a clear ruler withdraws the army and dismisses troops, leaves ten thousand men to farm, follows heaven's season, relies on earth's advantage, and awaits beatable barbarians—though they have not immediately submitted to punishment, the troops' resolution may be expected within months; the Qiang barbarians disintegrate—those who surrendered before and after number more than ten thousand seven hundred, and those who received words and departed total seventy parties—this is the means of sitting to dismember the Qiang barbarians.", idiomatic: "Yet a clear ruler withdraws the army, leaves ten thousand men to farm, follows heaven's season and earth's advantage, and awaits beatable barbarians. Though they have not yet submitted, the campaign may be settled within months. The Qiang are disintegrating: more than 10,700 have surrendered before and after, and seventy parties have departed on our word. This is the means of breaking the Qiang apart while sitting still." },
  { zh: "臣謹條不出兵留田便宜十二事：步兵九校、吏士萬人留屯，以為武備，因田致穀，威德並行，一也。", literal: "Your servant respectfully lists twelve advantages of not sending troops and leaving men to farm: nine commandants of foot soldiers and ten thousand officers and soldiers left to garrison as martial preparation, through farming obtaining grain, prestige and virtue both proceeding—first.", idiomatic: "Your servant respectfully lists twelve advantages of not sending troops and leaving men to farm: leave the nine foot-soldier commandants and ten thousand officers and men to garrison as martial preparation, obtain grain through farming, and let prestige and virtue proceed together—first." },
  { zh: "又因排折羌虜，令不得歸肥饒之地，貧破其眾，以成羌虜相畔之漸，二也。", literal: "Further, by pressing and breaking the Qiang barbarians, making them unable to return to fat and rich lands, impoverishing and breaking their masses, to accomplish the gradual process of Qiang barbarians turning on one another—second.", idiomatic: "Further, by pressing the Qiang and keeping them from rich pasture, impoverish and break their masses to bring about gradual defection among them—second." },
  { zh: "居民得並田作，不失農業，三也。", literal: "Residents can together farm without losing agriculture—third.", idiomatic: "Residents can farm together without losing the harvest—third." },
  { zh: "軍馬一月之食，度支田士一歲，罷騎兵以省大費，四也。", literal: "One month's food for army horses, estimating support for farming soldiers for one year, dismissing cavalry to save great expense—fourth.", idiomatic: "One month's feed for army horses supports farming soldiers for a year; dismiss cavalry to save great expense—fourth." },
  { zh: "至春，省甲士卒，循河、湟漕谷至臨羌，以示羌虜，揚威武，傳世折衝之具，五也。", literal: "When spring comes, reduce armored soldiers, follow the river and Huang to transport grain by canal to Linqiang to show the Qiang barbarians, display martial might—the means passed down through generations to repel foes—fifth.", idiomatic: "In spring, reduce armored troops and float grain along the river and Huang to Linqiang to show the Qiang our might—the means passed down through generations to repel foes—fifth." },
  { zh: "以閒暇時，下先所伐材，繕治郵亭，充入金城，六也。", literal: "In leisure time, bring down timber felled earlier, repair postal stations, and fill into Jincheng—sixth.", idiomatic: "In spare time, bring down the timber felled earlier, repair postal stations, and reinforce Jincheng—sixth." },
  { zh: "兵出，乘危徼幸，不出，令反畔之虜竄於風寒之地，離霜露、疾疫、瘃墮之患，坐得必勝之道，七也。", literal: "If troops go out, they exploit danger for lucky gain; if they do not go out, they make the rebellious barbarians flee to cold and windy lands, leave frost and dew, epidemics, and frostbite-falling afflictions, and sit and obtain the way of certain victory—the seventh.", idiomatic: "If troops go out, they exploit danger for lucky gain; if they do not go out, they make the rebellious barbarians flee to cold and windy lands, free from frost and dew, epidemics, and frostbite, and obtain certain victory by inaction—the seventh." },
  { zh: "無經阻、遠追、死傷之害，八也。", literal: "Without the harms of passing barriers, distant pursuit, and death and wounds—the eighth.", idiomatic: "Without the harms of passing barriers, distant pursuit, and death and wounds—the eighth." },
  { zh: "內不損威武之重，外不令虜得乘間之勢，九也。", literal: "Within, not damaging the weight of awe and might; without, not letting the barbarians obtain the momentum of exploiting gaps—the ninth.", idiomatic: "Within, not damaging the weight of awe and might; without, not letting the barbarians exploit openings—the ninth." },
  { zh: "又亡驚動河南大幵使生它變之憂，十也。", literal: "Also avoiding alarming Henan and the great Jian and causing other troubles to arise—the tenth.", idiomatic: "Also avoiding alarming the Henan and great Jian Qiang and causing other troubles to arise—the tenth." },
  { zh: "治隍陿中道橋，令可至鮮水以制西域，伸威千里，從枕席上過師，十一也。", literal: "Repairing bridges on the defile road of the middle route, making it possible to reach Fresh Water to control the Western Regions, extending authority a thousand li, passing troops from pillow and mat—the eleventh.", idiomatic: "Repairing bridges on the defile road of the middle route, making it possible to reach Fresh Water to control the Western Regions, extending authority a thousand li, passing troops as if from pillow and mat—the eleventh." },
  { zh: "大費既省，繇役豫息，以戒不虞，十二也。", literal: "Great expense already saved, corvée labor beforehand eased, to guard against the unexpected—the twelfth.", idiomatic: "Great expense already saved, corvée labor beforehand eased, to guard against the unexpected—the twelfth." },
  { zh: "留屯田得十二便，出兵失十二利，唯明詔采擇！", literal: "Retaining garrison farming obtains twelve conveniences; sending troops loses twelve benefits—only let the enlightened edict choose and adopt!", idiomatic: "Retaining garrison farming obtains twelve conveniences; sending troops loses twelve benefits—only let Your Majesty choose and adopt!" },
  { zh: "上復賜報曰：「兵決可期月而望者，謂今冬邪，謂何時也？", literal: "The emperor again bestowed a reply, saying: \"That the troops' decision can be expected within a month or so—does it mean this winter, or what time?", idiomatic: "The emperor again sent a reply, saying, \"That the troops' decision can be expected within a month or so—does it mean this winter, or what time?" },
  { zh: "將軍獨不計虜聞兵頗罷，且丁壯相聚，攻擾田者及道上屯兵，復殺略人民，將何以止之？", literal: "Does the general alone not reckon that the barbarians hearing troops are largely dismissed, and that able-bodied men will gather, attack and harass field workers and garrison troops on the roads, again kill and plunder the people—how will you stop it?", idiomatic: "Does the general alone not reckon that the barbarians, hearing troops are largely dismissed, will gather able-bodied men, attack and harass field workers and garrison troops on the roads, again kill and plunder the people—how will you stop it?" },
  { zh: "將軍孰計復奏！", literal: "General, think it through carefully and memorialize again!", idiomatic: "General, think it through carefully and memorialize again!" },
  { zh: "充國復奏曰：「臣聞兵以計為本，故多算勝少算。", literal: "Chongguo again memorialized, saying: \"Your subject has heard that troops take planning as the root; therefore many calculations defeat few calculations.", idiomatic: "Chongguo again memorialized, \"Your subject has heard that troops take planning as the root; therefore many calculations defeat few calculations." },
  { zh: "先零羌精兵，今餘不過七八千人，失地遠客，分散饑凍，畔還者不絕。", literal: "The Xianling Qiang's elite troops now remain no more than seven or eight thousand; having lost their lands they are distant guests, scattered, hungry and frozen, and those who turn and return do not cease.", idiomatic: "The Xianling Qiang's elite troops now remain no more than seven or eight thousand; having lost their lands they are distant guests, scattered, hungry and frozen, and those who turn and return do not cease." },
  { zh: "臣愚以為虜破壞可日月冀，遠在來春，故曰兵決可期月而望。", literal: "Your subject foolishly thinks the barbarians' destruction can be hoped for day by day, far off in next spring; therefore it is said the troops' decision can be expected within a month or so.", idiomatic: "Your subject foolishly thinks the barbarians' destruction can be hoped for day by day, far off in next spring; therefore it is said the troops' decision can be expected within a month or so." },
  { zh: "竊見北邊自敦煌至遼東萬一千五百餘里，乘塞列地有吏卒數千人，虜數以大眾攻之而不能害。", literal: "Your subject has privately seen that the northern border from Dunhuang to Liaodong is more than eleven thousand five hundred li; along the passes and in arrayed posts are several thousand officials and soldiers, and the barbarians repeatedly attack with great masses yet cannot harm them.", idiomatic: "Your subject has privately seen that the northern border from Dunhuang to Liaodong is more than eleven thousand five hundred li; along the passes and in arrayed posts are several thousand officials and soldiers, and the barbarians repeatedly attack with great masses yet cannot harm them." },
  { zh: "今騎兵雖罷，虜見屯田之士精兵萬人，從今盡三月，虜馬羸瘦，必不敢捐其妻子於他種中，遠涉山河而來為寇；", literal: "Now though cavalry is dismissed, the barbarians see garrison-farming soldiers and elite troops of ten thousand; from now through the third month, barbarian horses will be lean and thin—they surely will not dare abandon their wives and children among other tribes and come far across mountains and rivers to raid;", idiomatic: "Now though cavalry is dismissed, the barbarians see garrison-farming soldiers and elite troops of ten thousand; from now through the third month, barbarian horses will be lean and thin—they surely will not dare abandon their wives and children among other tribes and come far across mountains and rivers to raid;" },
  { zh: "亦不敢將其累重，還歸故地。", literal: "nor dare bring their baggage and return to their former lands.", idiomatic: "nor dare bring their baggage and return to their former lands." },
  { zh: "是臣之愚計所以度虜且必瓦解其處，不戰而自破之冊也。", literal: "This is your subject's foolish plan by which to gauge that the barbarians will surely disintegrate where they are—a policy of breaking themselves without battle.", idiomatic: "This is your subject's foolish plan by which to gauge that the barbarians will surely disintegrate where they are—a policy of breaking themselves without battle." },
  { zh: "至於虜小寇盜，時殺人民，其原未可卒禁。", literal: "As for the barbarians' small raids and banditry, occasionally killing the people—their source cannot be suddenly forbidden.", idiomatic: "As for the barbarians' small raids and banditry, occasionally killing the people—their source cannot be suddenly cut off." },
  { zh: "臣聞戰不必勝，不苟接刃；", literal: "Your subject has heard: battle need not be victorious—do not rashly cross blades;", idiomatic: "Your subject has heard: battle need not be victorious—do not rashly cross blades;" },
  { zh: "攻不必取，不苟勞眾。", literal: "attack need not take—do not rashly weary the masses.", idiomatic: "attack need not succeed—do not rashly weary the masses." },
  { zh: "誠令兵出，雖不能滅先零，但能令虜絕不為小寇，則出兵可也。", literal: "If troops truly go out, though they cannot destroy the Xianling, yet if they can only make the barbarians absolutely cease small raids, then sending troops is acceptable.", idiomatic: "If troops truly go out, though they cannot destroy the Xianling, yet if they can only make the barbarians absolutely cease small raids, then sending troops is acceptable." },
  { zh: "即今同是，而釋坐勝之道，從乘危之勢，往終不見利，空內自罷敝，貶重以自損，非所以示蠻夷也。", literal: "Yet now it is the same case, yet you release the way of sitting to victory and follow the momentum of exploiting danger; going you will in the end not see profit, vainly within you weary and exhaust yourselves, lower your weight and harm yourselves—it is not the means to show the barbarian Yi.", idiomatic: "Yet now it is the same case, yet you release the way of victory by inaction and follow the momentum of exploiting danger; going you will in the end not see profit, vainly within you weary and exhaust yourselves, lower your stature and harm yourselves—it is not the means to show the barbarians." },
  { zh: "又大兵一出，還不可復留，湟中亦未可空，如是，徭役復更發也。", literal: "Moreover, once great troops go out, they cannot again remain; Huangzhong also cannot be emptied—thus corvée labor will again be repeatedly raised.", idiomatic: "Moreover, once great troops go out, they cannot again remain; Huangzhong also cannot be emptied—thus corvée labor will again be repeatedly raised." },
  { zh: "臣愚以為不便。", literal: "Your subject foolishly thinks it inconvenient.", idiomatic: "Your subject foolishly thinks it unwise." },
  { zh: "臣竊自惟念：奉詔出塞，引軍遠擊，窮天子之精兵，散車甲於山野，雖亡尺寸之功。", literal: "Your subject privately reflects: obeying the edict to go beyond the passes, leading troops to strike far away, exhausting the Son of Heaven's elite troops, scattering chariots and armor in mountains and wilds—even without a foot of achievement.", idiomatic: "Your subject privately reflects: obeying the edict to go beyond the passes, leading troops to strike far away, exhausting the Son of Heaven's elite troops, scattering chariots and armor in mountains and wilds—even without the slightest achievement." },
  { zh: "偷得避嫌之便，而亡後咎餘責，此人臣不忠之利，非明主社稷之福也！", literal: "stealing the convenience of avoiding suspicion and having no later blame or remaining responsibility—this is the profit of an unloyal minister, not the blessing of a clear ruler's altars of soil and grain!", idiomatic: "stealing the convenience of avoiding suspicion and having no later blame or remaining responsibility—this is the profit of an unloyal minister, not the blessing of a clear ruler's state!" },
  { zh: "充國奏每上，輒下公卿議臣。", literal: "Whenever Chongguo's memorial went up, it was immediately sent down to the excellencies and ministers to discuss.", idiomatic: "Whenever Chongguo's memorial went up, it was immediately sent down to the excellencies and ministers to discuss." },
  { zh: "初是充國計者什三；", literal: "At first those who favored Chongguo's plan were three-tenths;", idiomatic: "At first those who favored Chongguo's plan were three-tenths;" },
  { zh: "中什五；", literal: "in the middle five-tenths;", idiomatic: "in the middle five-tenths;" },
  { zh: "最後什八。", literal: "at the end eight-tenths.", idiomatic: "at the end eight-tenths." },
  { zh: "有詔詰前言不便者，皆頓首服。", literal: "An edict questioned those who earlier said it was inconvenient; all knocked their heads and submitted.", idiomatic: "An edict questioned those who earlier said it was unwise; all knocked their heads and submitted." },
  { zh: "魏相曰：「臣愚不習兵事利害。", literal: "Wei Xiang said: \"Your subject is foolish and does not understand the benefits and harms of military affairs.", idiomatic: "Wei Xiang said, \"Your subject is foolish and does not understand the benefits and harms of military affairs." },
  { zh: "後將軍數畫軍冊，其言常是，臣任其計必可用也。", literal: "The Rear General repeatedly drew up military plans; his words are often correct—your subject trusts his plan will surely be usable.", idiomatic: "The Rear General repeatedly drew up military plans; his words are often correct—your subject trusts his plan will surely be usable." },
  { zh: "」上於是報充國，嘉納之；", literal: "\" The emperor thereupon replied to Chongguo and praised and adopted it;", idiomatic: "\" The emperor thereupon replied to Chongguo and praised and adopted it;" },
  { zh: "亦以破羌、強弩將軍數言當擊，以是兩從其計，詔兩將軍與中郎將卬出擊。", literal: "also because the Po-Qiang and Strong Crossbow generals repeatedly said they ought to strike, the emperor accordingly followed both plans in part and ordered the two generals and Palace Gentleman Ang to go out and strike.", idiomatic: "also because the Po-Qiang and Strong Crossbow generals repeatedly said they ought to strike, the emperor accordingly followed both plans in part and ordered the two generals and Palace Gentleman Ang to go out and strike." },
  { zh: "強弩出，降四千餘人；", literal: "Strong Crossbow went out and received the surrender of more than four thousand men;", idiomatic: "Strong Crossbow went out and received the surrender of more than four thousand men;" },
  { zh: "破羌斬首二千級；", literal: "Po-Qiang beheaded two thousand heads;", idiomatic: "Po-Qiang beheaded two thousand heads;" },
  { zh: "中郎將卬斬首降者亦二千餘級；", literal: "Palace Gentleman Ang's beheaded heads and those who surrendered also exceeded two thousand heads;", idiomatic: "Palace Gentleman Ang's beheaded heads and those who surrendered also exceeded two thousand;" },
  { zh: "而充國所降復得五千餘人。", literal: "while those Chongguo received in surrender again obtained more than five thousand men.", idiomatic: "while those Chongguo received in surrender again obtained more than five thousand men." },
  { zh: "詔罷兵，獨充國留屯田。", literal: "An edict dismissed the troops; only Chongguo remained for garrison farming.", idiomatic: "An edict dismissed the troops; only Chongguo remained for garrison farming." },
  { zh: "----6大司農朱邑卒。", literal: "----6 Grand Minister of Agriculture Zhu Yi died.", idiomatic: "----6 Grand Minister of Agriculture Zhu Yi died." },
  { zh: "上以其循吏，閔惜之，詔賜其子黃金百斤，以奉其祭祀。", literal: "The emperor because he was an orderly official pitied and cherished him and ordered his son bestowed a hundred catties of gold to support his sacrifices.", idiomatic: "The emperor because he was an orderly official pitied him and ordered his son bestowed a hundred catties of gold to support his sacrifices." },
  { zh: "----7是歲，前將軍、龍額侯韓增為大司馬、車騎將軍。", literal: "----7 That year, Former General, Marquis of Dragon Neck Han Zeng became Grand Marshal and General of Chariots and Cavalry.", idiomatic: "----7 That year, Former General, Marquis of Dragon Neck Han Zeng became Grand Marshal and General of Chariots and Cavalry." },
  { zh: "----8丁令比三歲鈔盜匈奴，殺略數千人。", literal: "----8 The Dingling for three years running raided and plundered the Xiongnu, killing and carrying off several thousand men.", idiomatic: "----8 The Dingling for three years running raided and plundered the Xiongnu, killing and carrying off several thousand men." },
  { zh: "匈奴遣萬餘騎往擊之，無所得。", literal: "The Xiongnu dispatched more than ten thousand cavalry to go strike them and obtained nothing.", idiomatic: "The Xiongnu dispatched more than ten thousand cavalry to strike them and obtained nothing." },
  { zh: "1春，二月，以鳳皇、甘露降集京師，赦天下。", literal: "1 In spring, the second month, because phoenixes and sweet dew descended and gathered at the capital, amnesty for all under Heaven.", idiomatic: "1 In spring, the second month, because phoenixes and sweet dew descended and gathered at the capital, there was an amnesty for all under Heaven." },
  { zh: "----2夏，五月，趙充國奏言：「羌本可五萬人軍，凡斬首七千六百級，降者三萬一千二百人，溺河湟、飢餓者五六千人，定計遺脫與煎鞏、黃羝俱亡者不過四千人。", literal: "----2 In summer, the fifth month, Zhao Chongguo memorialized, saying: \"The Qiang originally could field fifty thousand troops; in all beheaded heads were seven thousand six hundred, those who surrendered thirty-one thousand two hundred, those drowned in the Huang and Qiang rivers and starved five or six thousand; by fixed reckoning those who escaped and fled together with the Jianrong and Huangdi cannot exceed four thousand.", idiomatic: "----2 In summer, the fifth month, Zhao Chongguo memorialized, \"The Qiang originally could field fifty thousand troops; in all beheaded heads were seven thousand six hundred, those who surrendered thirty-one thousand two hundred, those drowned in the Huang and Qiang rivers and starved five or six thousand; by fixed reckoning those who escaped and fled together with the Jianrong and Huangdi cannot exceed four thousand." },
  { zh: "羌靡忘等自詭必得，請罷屯兵！", literal: "The Qiang Moyang and others falsely claimed they would surely be captured and requested dismissal of garrison troops!", idiomatic: "The Qiang Moyang and others falsely claimed they would surely be captured and requested dismissal of garrison troops!" },
  { zh: "」奏可。", literal: "\" The memorial was approved.", idiomatic: "\" The memorial was approved." },
  { zh: "充國振旅而還。", literal: "Chongguo shook out his troops and returned.", idiomatic: "Chongguo shook out his troops and returned." },
  { zh: "所善浩星賜迎說充國曰：「眾人皆以破羌、強弩出擊，多斬首、生降，虜以破壞。", literal: "His friend Haoxing Ci came to meet him and urged Chongguo, saying: \"Everyone thinks that because the Po-Qiang and Strong Crossbow generals went out and struck, beheading many and taking live surrenders, the barbarians were destroyed.", idiomatic: "His friend Haoxing Ci came to meet him and urged Chongguo, \"Everyone thinks that because the Po-Qiang and Strong Crossbow generals went out and struck, beheading many and taking live surrenders, the barbarians were destroyed." },
  { zh: "然有識者以為虜勢窮困，兵雖不出，必自服矣。", literal: "Yet those with understanding hold that the barbarians' power was exhausted and trapped; though troops did not go out, they would surely submit of themselves.", idiomatic: "Yet those with understanding hold that the barbarians' power was exhausted and trapped; though troops did not go out, they would surely submit of themselves." },
  { zh: "將軍即見，宜歸功於二將軍出擊，非愚臣所及。", literal: "When the general is soon received in audience, you ought to attribute merit to the two generals' going out to strike—not what your foolish subject could reach.", idiomatic: "When the general is soon received in audience, you ought to attribute merit to the two generals' going out to strike—not what your foolish subject could reach." },
  { zh: "如此，將軍計未失也。", literal: "Thus the general's plan would not have failed.", idiomatic: "Thus the general's plan would not have failed." },
  { zh: "」充國曰：「吾年老矣，爵位已極，豈嫌伐一時事以欺明主哉！", literal: "\" Chongguo said: \"I am old; rank and title have reached the limit—how would I begrudge claiming one timely affair to deceive a clear ruler!", idiomatic: "\" Chongguo said, \"I am old; rank and title have reached the limit—how would I begrudge claiming one timely affair to deceive a clear ruler!" },
  { zh: "兵勢，國之大事，當為後法。", literal: "Military momentum is a great affair of the state and ought to be a model for later times.", idiomatic: "Military momentum is a great affair of the state and ought to be a model for later times." },
  { zh: "老臣不以餘命壹為陛下明言兵之利害，卒死，誰當復言之者！", literal: "This old minister will not use his remaining life solely to speak clearly to Your Majesty the benefits and harms of troops; when I finally die, who will again speak of them!", idiomatic: "This old minister will not use his remaining life solely to speak clearly to Your Majesty the benefits and harms of troops; when I finally die, who will again speak of them!" },
  { zh: "」卒以其意對。", literal: "\" In the end he answered according to his own mind.", idiomatic: "\" In the end he answered according to his own mind." },
  { zh: "上然其計，罷遣辛武賢歸酒泉太守官，充國復為後將軍。", literal: "The emperor approved his plan, dismissed and sent Xin Wuxian back to his post as Governor of Jiuquan, and Chongguo again became Rear General.", idiomatic: "The emperor approved his plan, dismissed and sent Xin Wuxian back to his post as Governor of Jiuquan, and Chongguo again became Rear General." },
  { zh: "秋，羌若零、離留、且種、兒庫共斬先零大豪猶非、楊玉首，及諸豪弟澤、陽雕、良兒、靡忘皆帥煎鞏、黃羝之屬四千餘人降。", literal: "In autumn, the Qiang Ruoling, Lilu, Qiezhong, and Erku jointly beheaded the Xianling great chieftains Youfei and Yangyu's heads, and all the great chieftains Di Ze, Yangdiao, Lianger, and Moyang led more than four thousand of the Jianrong and Huangdi and their kind to surrender.", idiomatic: "In autumn, the Qiang Ruoling, Lilu, Qiezhong, and Erku jointly beheaded the Xianling great chieftains Youfei and Yangyu, and all the great chieftains Di Ze, Yangdiao, Lianger, and Moyang led more than four thousand of the Jianrong and Huangdi and their kind to surrender." },
  { zh: "漢封若零、弟澤二人為帥眾王，餘皆為侯、為君。", literal: "Han enfeoffed Ruoling and Di Ze as kings who lead the masses; the rest all became marquises or lords.", idiomatic: "Han enfeoffed Ruoling and Di Ze as kings who lead the masses; the rest all became marquises or lords." },
  { zh: "初置金城屬國以處降羌。", literal: "For the first time the Dependent State of Jincheng was established to settle the surrendered Qiang.", idiomatic: "For the first time the Dependent State of Jincheng was established to settle the surrendered Qiang." },
  { zh: "詔舉可護羌校尉者。", literal: "An edict ordered recommendation of one fit to be Colonel Protector of the Qiang.", idiomatic: "An edict ordered recommendation of one fit to be Colonel Protector of the Qiang." },
  { zh: "時充國病，四府舉辛武賢小弟湯。", literal: "At that time Chongguo was ill; the four offices recommended Xin Wuxian's younger brother Tang.", idiomatic: "At that time Chongguo was ill; the four offices recommended Xin Wuxian's younger brother Tang." },
  { zh: "充國遽起，奏：「湯使酒，不可典蠻夷。", literal: "Chongguo hastily rose and memorialized: \"Tang is given to drink and cannot administer the barbarian Yi.", idiomatic: "Chongguo hastily rose and memorialized, \"Tang is given to drink and cannot administer the barbarians." },
  { zh: "不如湯兄臨眾。", literal: "He is not equal to Tang's elder brother Linzhong.", idiomatic: "He is not equal to Tang's elder brother Linzhong." },
  { zh: "」時湯已拜受節，有詔更用臨眾。", literal: "\" At that time Tang had already received appointment and accepted the staff; an edict changed it and employed Linzhong.", idiomatic: "\" At that time Tang had already received appointment and accepted the staff; an edict changed it and employed Linzhong." },
  { zh: "後臨眾病免，五府復舉湯。", literal: "Later Linzhong was dismissed because of illness; the five offices again recommended Tang.", idiomatic: "Later Linzhong was dismissed because of illness; the five offices again recommended Tang." },
  { zh: "湯數醉酗羌人，羌人反畔，卒如充國之言。", literal: "Tang repeatedly when drunk abused the Qiang; the Qiang turned and rebelled—in the end it was as Chongguo had said.", idiomatic: "Tang repeatedly when drunk abused the Qiang; the Qiang turned and rebelled—in the end it was as Chongguo had said." },
  { zh: "辛武賢深恨充國，上書告中郎將卬洩省中語，下吏，自殺。", literal: "Xin Wuxian deeply resented Chongguo, memorialized accusing Palace Gentleman Ang of leaking palace secrets, was sent down to officials, and killed himself.", idiomatic: "Xin Wuxian deeply resented Chongguo, memorialized accusing Palace Gentleman Ang of leaking palace secrets, was sent down to officials, and killed himself." },
  { zh: "----3司隸校尉魏郡蓋寬饒，剛直公清，數干犯上意。", literal: "----3 Director of the Metropolitan Region Gai Kuanrao of Wei Commandery was firm, upright, fair, and clear, and repeatedly offended the emperor's intent.", idiomatic: "----3 Director of the Metropolitan Region Gai Kuanrao of Wei Commandery was firm, upright, fair, and clear, and repeatedly offended the emperor's intent." },
  { zh: "時上方用刑法，任中書官，寬饒奏封事曰：「方今聖道浸微，儒術不行，以刑餘為周、召，以法律為《詩》、《書》。", literal: "At that time the emperor above was employing penal law and trusting Palace Secretariat officials; Kuanrao memorialized a sealed report, saying: \"Now the sage's way is gradually fading, Confucian learning is not practiced, using the mutilated as Duke of Zhou and Duke of Shao, using law as the Odes and Documents.", idiomatic: "At that time the emperor was employing penal law and trusting Palace Secretariat officials; Kuanrao memorialized a sealed report, \"Now the sage's way is gradually fading, Confucian learning is not practiced, using eunuchs as Duke of Zhou and Duke of Shao, using law as the Odes and Documents." },
  { zh: "」又引《易傳》言：「五帝官天下，三王家天下。", literal: "\" He also cited the Yi Zhuan, saying: \"The Five Emperors officered all under Heaven; the Three Kings familied all under Heaven.", idiomatic: "\" He also cited the Yi Zhuan, saying, \"The Five Emperors officered all under Heaven; the Three Kings familied all under Heaven." },
  { zh: "家以傳子孫，官以傳賢聖。", literal: "The family passes to sons and grandsons; the office passes to the worthy and sage.", idiomatic: "The family passes to sons and grandsons; the office passes to the worthy and sage." },
  { zh: "」書奏，上以為寬饒怨謗，下其書中二千石。", literal: "\" When the writing was memorialized, the emperor thought Kuanrao was resentful and slanderous and sent his writing down among the two-thousand-bushel officials.", idiomatic: "\" When the memorial was submitted, the emperor thought Kuanrao was resentful and slanderous and sent his writing down among the two-thousand-bushel officials." },
  { zh: "時執金吾議，以為「寬饒旨意欲求禪，大逆不道！", literal: "At that time the Commandant of Convoy deliberated, holding that \"Kuanrao's intent sought abdication in favor of another—great rebellion and not the Way!", idiomatic: "At that time the Commandant of Convoy deliberated, holding that \"Kuanrao's intent sought abdication in favor of another—great rebellion and not the Way!" },
  { zh: "」諫大夫鄭昌愍傷寬饒忠直憂國，以言事不當意而為文吏所詆挫，上書訟寬饒曰：「臣聞山有猛獸，藜藿為之不採；", literal: "\" Remonstrance Grandee Zheng Chang pitied and grieved for Kuanrao's loyal uprightness and concern for the state, that because his words on affairs did not suit the intent he was slandered and thwarted by cultured officials; he memorialized in Kuanrao's defense, saying: \"Your subject has heard that where mountains have fierce beasts, brambles and beans are not picked for them;", idiomatic: "\" Remonstrance Grandee Zheng Chang pitied Kuanrao's loyal uprightness and concern for the state, that because his words on affairs did not suit the intent he was slandered and thwarted by cultured officials; he memorialized in Kuanrao's defense, \"Your subject has heard that where mountains have fierce beasts, brambles and beans are not picked for them;" },
  { zh: "國有忠臣，奸邪為之不起。", literal: "where a state has loyal ministers, wickedness and evil do not arise for them.", idiomatic: "where a state has loyal ministers, wickedness and evil do not arise for them." },
  { zh: "司隸校尉寬饒，居不求安，食不求飽；", literal: "Director of the Metropolitan Region Kuanrao in dwelling did not seek ease, in eating did not seek fullness;", idiomatic: "Director of the Metropolitan Region Kuanrao in dwelling did not seek ease, in eating did not seek fullness;" },
  { zh: "進有憂國之心，退有死節之義；", literal: "advancing he had a heart that worried for the state, retreating he had the righteousness of dying for principle;", idiomatic: "advancing he had a heart that worried for the state, retreating he had the righteousness of dying for principle;" },
  { zh: "上無許、史之屬，下無金、張之托；", literal: "above he had no Xu or Shi faction, below he had no Jin or Zhang patronage;", idiomatic: "above he had no Xu or Shi faction, below he had no Jin or Zhang patronage;" },
  { zh: "職在司察，直道而行，多仇少與。", literal: "his post was in oversight and inspection; he walked the straight way—many enemies, few allies.", idiomatic: "his post was in oversight and inspection; he walked the straight way—many enemies, few allies." },
  { zh: "上書陳國事，有司劾以大辟。", literal: "Memorializing to set forth state affairs, the responsible offices impeached him for the great execution.", idiomatic: "Memorializing to set forth state affairs, the responsible offices impeached him for capital punishment." },
  { zh: "臣幸得從大夫之後，官以諫為名，不敢不言！", literal: "Your subject by luck obtained to follow after grandees; his office takes remonstrance as its name—he dares not be silent!", idiomatic: "Your subject by luck obtained to follow after grandees; his office takes remonstrance as its name—he dares not be silent!" },
  { zh: "」上不聽。", literal: "\" The emperor did not listen.", idiomatic: "\" The emperor did not listen." },
  { zh: "九月，下寬饒吏。", literal: "In the ninth month, Kuanrao was sent down to officials.", idiomatic: "In the ninth month, Kuanrao was sent down to officials." },
  { zh: "寬饒引佩刀自剄北闕下，眾莫不憐之。", literal: "Kuanrao drew his girdle knife and cut his own throat below the Northern Gate; none did not pity him.", idiomatic: "Kuanrao drew his girdle knife and cut his own throat below the Northern Gate; none did not pity him." },
  { zh: "----4匈奴虛閭權渠單于將十餘萬騎旁塞獵，欲入邊為寇。", literal: "----4 The Xiongnu chanyu Xulü Quanqu was about to lead more than a hundred thousand cavalry to hunt along the border passes and wished to enter the border to raid.", idiomatic: "----4 The Xiongnu chanyu Xulü Quanqu was about to lead more than a hundred thousand cavalry to hunt along the border passes and wished to enter the border to raid." },
  { zh: "未至，會其民題除渠堂亡降漢言狀，漢以為言兵鹿奚鹿盧侯，而遣後將軍趙充國將兵四萬餘騎，屯緣邊九郡備虜。", literal: "Before he arrived, it happened that his subject Tichu Qutang fled and surrendered to Han and reported the situation; Han made him Marquis Yanbing Luxi Lulu and dispatched Rear General Zhao Chongguo to lead more than forty thousand cavalry to garrison along the border in nine commanderies to guard against the barbarians.", idiomatic: "Before he arrived, it happened that his subject Tichu Qutang fled and surrendered to Han and reported the situation; Han made him Marquis Yanbing Luxi Lulu and dispatched Rear General Zhao Chongguo to lead more than forty thousand cavalry to garrison along the border in nine commanderies to guard against the barbarians." },
  { zh: "月餘，單于病歐血，因不敢入，還去，即罷兵。", literal: "After more than a month the chanyu was ill, vomiting blood, and therefore did not dare enter; he returned and departed, and immediately dismissed the troops.", idiomatic: "After more than a month the chanyu was ill, vomiting blood, and therefore did not dare enter; he returned and departed, and immediately dismissed the troops." },
  { zh: "乃使題王都犁胡次等入漢請和親，未報。", literal: "He thereupon sent Diwang Dulihu Ci and others to enter Han to request heqin marriage alliance; no reply had yet been made.", idiomatic: "He thereupon sent Diwang Dulihu Ci and others to enter Han to request heqin marriage alliance; no reply had yet been made." },
  { zh: "會單于死。", literal: "It happened the chanyu died.", idiomatic: "It happened the chanyu died." },
  { zh: "虛閭權渠單于始立，而黜顓渠閼氏。", literal: "Chanyu Xulü Quanqu had just been established and deposed Zhuanqu Yanshi.", idiomatic: "Chanyu Xulü Quanqu had just been established and deposed Zhuanqu Yanshi." },
  { zh: "顓渠閼氏即與右賢王屠耆堂私通，右賢王會龍城而去。", literal: "Zhuanqu Yanshi thereupon privately communicated with the Right Wisdom King Tujitang; the Right Wisdom King met at Dragon City and departed.", idiomatic: "Zhuanqu Yanshi thereupon privately communicated with the Right Wisdom King Tujitang; the Right Wisdom King met at Dragon City and departed." },
  { zh: "顓渠閼氏語以單于病甚，且勿遠。", literal: "Zhuanqu Yanshi told him the chanyu was gravely ill and for the time being not to go far.", idiomatic: "Zhuanqu Yanshi told him the chanyu was gravely ill and for the time being not to go far." },
  { zh: "後數日，單于死，用事貴人郝宿王刑未央使人號諸王，未至，顓渠閼氏與其弟左大將且渠都隆奇謀，立右賢王為握衍朐鞮單于。", literal: "Several days later the chanyu died; the powerful noble Haosu King Xing Weiyang sent men to summon the kings; before they arrived, Zhuanqu Yanshi with her younger brother Left Grand General Qiequ Dulongqi plotted and established the Right Wisdom King as chanyu Woyan Judi.", idiomatic: "Several days later the chanyu died; the powerful noble Haosu King Xing Weiyang sent men to summon the kings; before they arrived, Zhuanqu Yanshi with her younger brother Left Grand General Qiequ Dulongqi plotted and established the Right Wisdom King as chanyu Woyan Judi." },
  { zh: "握衍朐鞮單于者，烏維單于耳孫也。", literal: "Chanyu Woyan Judi was a descendant of Chanyu Wuwie.", idiomatic: "Chanyu Woyan Judi was a descendant of Chanyu Wuwie." },
  { zh: "握衍朐鞮單于立，凶惡，殺刑未央等而任用都隆奇，又盡免虛閭權渠子弟近親而自以其子弟代之。", literal: "When Chanyu Woyan Judi was established, he was fierce and wicked; he killed Xing Weiyang and others and employed Dulongqi, and again entirely dismissed Xulü Quanqu's sons, younger brothers, and close kin and on his own replaced them with his sons and younger brothers.", idiomatic: "When Chanyu Woyan Judi was established, he was fierce and wicked; he killed Xing Weiyang and others and employed Dulongqi, and again entirely dismissed Xulü Quanqu's sons, younger brothers, and close kin and on his own replaced them with his sons and younger brothers." },
  { zh: "虛閭權渠單于子稽侯狦既不得立，亡歸妻父烏禪幕。", literal: "Chanyu Xulü Quanqu's son Ji Houxing, having not obtained installation, fled and returned to his wife's father Wuchanmu.", idiomatic: "Chanyu Xulü Quanqu's son Ji Houxing, having not obtained installation, fled and returned to his wife's father Wuchanmu." },
  { zh: "烏禪幕者，本康居、烏孫間小國，數見侵暴，率其眾數千人降匈奴，狐鹿姑單于以其弟子日逐王姊妻之，使長其眾，居右地。", literal: "Wuchanmu was originally a small state between Kangju and Wusun, repeatedly seeing invasion and violence; he led his masses of several thousand to surrender to the Xiongnu; Chanyu Hulu Gu made his younger brother's daughter, the Lady of the Day-by-Day Pursuit King, marry him, had him grow his masses, and dwell in the right territory.", idiomatic: "Wuchanmu was originally a small state between Kangju and Wusun, repeatedly seeing invasion and violence; he led his masses of several thousand to surrender to the Xiongnu; Chanyu Hulu Gu had his younger brother's daughter, the Lady of the Day-by-Day Pursuit King, marry him, had him grow his masses, and dwell in the right territory." },
  { zh: "日逐王先賢撣，其父左賢王當為單于，讓狐鹿姑單于，狐鹿姑單于許立之。", literal: "The Rizhu King Xianxian Chan—his father the Left Wise King ought to have become Chanyu—yielded to Chanyu Huluqu; Chanyu Huluqu promised to install him.", idiomatic: "The Rizhu King Xianxian Chan—his father the Left Wise King ought to have become Chanyu—yielded to Chanyu Huluqu, who promised to install him." },
  { zh: "國人以故頗言日逐王當為單于。", literal: "The state people for this reason widely said the Rizhu King ought to become Chanyu.", idiomatic: "For this reason the Xiongnu widely said the Rizhu King ought to become Chanyu." },
  { zh: "日逐王素與握衍朐鞮單于有隙，即率其眾欲降漢，使人至渠犁，與騎都尉鄭吉相聞。", literal: "The Rizhu King had long had a rift with Chanyu Woyanqudi; he then led his masses wishing to submit to the Han, sent men to Queli to communicate with Commandant of Cavalry Zheng Ji.", idiomatic: "The Rizhu King had long been at odds with Chanyu Woyanqudi; he then led his followers intending to surrender to the Han and sent envoys to Queli to contact Commandant of Cavalry Zheng Ji." },
  { zh: "吉發渠犁、龜茲諸國五萬人迎日逐王口萬二千人、小王將十二人，隨吉至河曲，頗有亡者，吉追斬之，遂將詣京師。", literal: "Ji dispatched fifty thousand men from Queli, Kucha, and other states to welcome the Rizhu King—口 twelve thousand persons and twelve minor kings and generals—who followed Ji to Hequ; there were quite a few who fled; Ji pursued and beheaded them, then led them to the capital.", idiomatic: "Ji mobilized fifty thousand men from Queli, Kucha, and other states to welcome the Rizhu King with twelve thousand followers and twelve minor kings and generals; they followed Ji to Hequ. Many fled en route; Ji pursued and executed them, then escorted the rest to the capital." },
  { zh: "漢封日逐王為歸德侯。", literal: "The Han enfeoffed the Rizhu King as Marquis of Returned Virtue.", idiomatic: "The Han enfeoffed the Rizhu King as Marquis of Returned Virtue." },
  { zh: "吉既破車師，降日逐，威震西域，遂並護車師以西北道，故號都護。", literal: "After Ji had broken Cheshi and received the Rizhu King's surrender, his might shook the Western Regions; he then jointly protected Cheshi on the northwest road—therefore titled Protector General.", idiomatic: "After Ji had defeated Cheshi and accepted the Rizhu King's surrender, his prestige shook the Western Regions; he then took joint charge of Cheshi along the northwest route—hence the title Protector General." },
  { zh: "都護之置，自吉始焉。", literal: "The establishment of the Protector General began with Ji.", idiomatic: "The office of Protector General began with Ji." },
  { zh: "上封吉為安遠侯。", literal: "The emperor enfeoffed Ji as Marquis of Secure Distance.", idiomatic: "The emperor enfeoffed Ji as Marquis of Secure Distance." },
  { zh: "吉於是中西域而立莫府，治烏壘城，去陽關二千七百餘里。", literal: "Ji thereupon centered on the Western Regions and established a headquarters, governing Wulei city, more than two thousand seven hundred li from Yang Pass.", idiomatic: "Ji thereupon made the Western Regions his center and established a headquarters at Wulei, more than twenty-seven hundred li from Yang Pass." },
  { zh: "匈奴益弱，不敢爭西域，僮僕都尉由此罷。", literal: "The Xiongnu grew ever weaker, did not dare contend for the Western Regions, and the Slave Commandant was thereby abolished.", idiomatic: "The Xiongnu grew ever weaker and no longer dared contest the Western Regions; the Slave Commandant post was abolished." },
  { zh: "都護督察烏孫、康居等三十六國動靜，有變以聞，可安輯，安輯之，不可者誅伐之，漢之號令班西域矣。", literal: "The Protector General inspected the movements of thirty-six states including Wusun and Kangju; when there were changes he reported; those that could be pacified he pacified; those that could not he punished and attacked—Han's orders and commands were issued throughout the Western Regions.", idiomatic: "The Protector General monitored Wusun, Kangju, and thirty-six other states; he reported any disturbance, pacified those that could be pacified, and punished those that could not—so Han orders reached throughout the Western Regions." },
  { zh: "握衍朐鞮單于更立其從兄薄胥堂為日逐王。", literal: "Chanyu Woyanqudi again established his elder cousin's son Boxu Tang as Rizhu King.", idiomatic: "Chanyu Woyanqudi installed his elder cousin's son Boxu Tang as the new Rizhu King." },
  { zh: "----5烏孫昆彌翁歸靡因長羅侯常惠上書：「願以漢外孫元貴靡為嗣，得令復尚漢公主，結婚重親，畔絕匈奴。", literal: "----5 Wusun Kunmi Weng Guimie through Marquis Changluo Chang Hui submitted a memorial: \"Your subject wishes to make the Han's maternal grandson Yuan Guimie the successor, obtain an order again to marry a Han princess, marry by affinity with redoubled closeness, rebel and sever from the Xiongnu.", idiomatic: "----5 Wusun Kunmi Weng Guimie, through Marquis Changluo Chang Hui, submitted a memorial: \"I wish to make the Han emperor's maternal grandson Yuan Guimie my heir, obtain permission again to marry a Han princess, bind our houses in redoubled kinship, and break with the Xiongnu.\"" },
  { zh: "」詔下公卿議，大鴻臚蕭望之以為：「烏孫絕域，變故難保，不可許。", literal: "\" An edict went down to the dukes and ministers for deliberation; Grand Herald Xiao Wangzhi held: \"Wusun is a far region; changes and emergencies are hard to secure—cannot grant.", idiomatic: "\" The edict was referred to the chief ministers. Grand Herald Xiao Wangzhi argued, \"Wusun lies in a remote land; its fortunes are hard to guarantee—we should not grant this.\"" },
  { zh: "」上美烏孫新立大功，又重絕故業，乃以烏孫主解憂弟相夫為公主，盛為資送而遣之，使常惠送之至敦煌。", literal: "\" The emperor prized Wusun's newly establishing great merit and also valued severing the old tie; he therefore took the Wusun princess Jieyou's younger brother Xiangfu as princess, lavishly provided dowry and sent her off, and had Chang Hui escort her to Dunhuang.", idiomatic: "\" The emperor admired Wusun's recent great service and prized breaking the old tie; he therefore took Princess Jieyou's younger brother Xiangfu as the new princess, sent her off with a lavish dowry, and had Chang Hui escort her as far as Dunhuang." },
  { zh: "未出塞，聞翁歸靡死，烏孫貴人共從本約立岑娶子泥靡為昆彌，號狂王。", literal: "Before leaving the frontier pass, word came that Weng Guimie had died; Wusun nobles jointly following the original pact established Nimi, son of Cenqu, as Kunmi, titled Mad King.", idiomatic: "Before she had crossed the border, news arrived that Weng Guimie was dead; Wusun nobles jointly followed the original agreement and made Cenqu's son Nimi Kunmi, styled the Mad King." },
  { zh: "常惠上書：「願留少主敦煌。", literal: "Chang Hui submitted: \"Your subject wishes to retain the young mistress at Dunhuang.", idiomatic: "Chang Hui submitted, \"I ask to keep the young princess at Dunhuang.\"" },
  { zh: "」惠馳至烏孫，責讓不立元貴靡為昆彌，還迎少主。", literal: "\" Hui galloped to Wusun, reproached them for not establishing Yuan Guimie as Kunmi, and returned to welcome the young mistress.", idiomatic: "\" Hui rode posthaste to Wusun, rebuked them for not making Yuan Guimie Kunmi, and returned to escort the young princess." },
  { zh: "事下公卿，望之復以為「烏孫持兩端，難約結。", literal: "The affair went down to the dukes and ministers; Wangzhi again held that \"Wusun holds two ends—hard to covenant.", idiomatic: "The matter was referred to the chief ministers. Wangzhi again argued, \"Wusun sits on the fence; it is hard to bind them by treaty.\"" },
  { zh: "今少主以元貴靡不立而還，信無負於夷狄，中國之福也。", literal: "Now the young mistress returns because Yuan Guimie was not established—truly there is no harm to the Yi-Di; it is the Central States' fortune.", idiomatic: "If the young princess returns now because Yuan Guimie was not installed, we truly owe the barbarians nothing—it is a blessing for the empire." },
  { zh: "少主不止，繇役將興。", literal: "If the young mistress does not stop, corvée labor will arise.", idiomatic: "If she does not turn back, corvée and war will follow." },
  { zh: "」天子從之，徵還少主。", literal: "\" The Son of Heaven followed this and summoned back the young mistress.", idiomatic: "\" The emperor agreed and recalled the young princess." },
  { zh: "1春，三月，丙辰，高平憲侯魏相薨。", literal: "1 Spring, third month, on bingchen, Marquis Xian of Gaoping Wei Xiang passed away.", idiomatic: "1 In spring, the third month, on bingchen, Marquis Xian of Gaoping Wei Xiang died." },
  { zh: "夏，四月，戊辰，丙吉為丞相。", literal: "Summer, fourth month, on wuchen, Bing Ji became chancellor.", idiomatic: "In summer, the fourth month, on wuchen, Bing Ji became chancellor." },
  { zh: "吉上寬大，好禮讓，不親小事，時人以為知大體。", literal: "Ji was broad and magnanimous, fond of courtesy and yielding, did not personally handle small matters—at the time people considered him to know the great pattern.", idiomatic: "Ji was magnanimous, loved courtesy and deference, and did not busy himself with petty affairs; contemporaries thought he grasped the larger pattern of governance." },
  { zh: "----2秋，七月，甲子，大鴻臚蕭望之為御史大夫。", literal: "----2 Autumn, seventh month, on jiazi, Grand Herald Xiao Wangzhi became Censor-in-Chief.", idiomatic: "----2 In autumn, the seventh month, on jiazi, Grand Herald Xiao Wangzhi became Censor-in-Chief." },
  { zh: "----3八月，詔曰：「吏不廉平，則治道衰。", literal: "----3 Eighth month, an edict said: \"If officials are not incorrupt and fair, then the way of governance declines.", idiomatic: "----3 In the eighth month, an edict said, \"When officials are neither honest nor impartial, the way of governance declines.\"" },
  { zh: "今小吏皆勤事而俸祿薄，欲無侵漁百姓，難矣！", literal: "Now petty officials all diligently serve yet salaries are thin—wishing that there be no encroachment and fishing of the hundred surnames is hard!", idiomatic: "Petty officials now work diligently yet their pay is meager; to expect that they will not prey on the common people is difficult!\"" },
  { zh: "其益吏百石已下俸十五。", literal: "Let the salaries of those of one hundred shi and below be increased by fifteen.", idiomatic: "Increase the salaries of officials at one hundred shi and below by fifteen." },
  { zh: "」----4是歲，東郡太守韓延壽為左馮翊。", literal: "\" ----4 That year, Governor of Dongjun Han Yanshou became Left Governor of Jingzhao.", idiomatic: "\" ----4 That year, Governor of Dong Commandery Han Yanshou became Left Governor of Jingzhao." },
  { zh: "始，延壽為穎川太守，穎川承趙廣漢構會吏民之後，俗多怨讎。", literal: "At the beginning, Yanshou was Governor of Yingchuan; Yingchuan, inheriting after Zhao Guanghan's framing of officials and people, had customs with much resentment and vendetta.", idiomatic: "Earlier, when Yanshou was governor of Yingchuan, the commandery still bore the aftermath of Zhao Guanghan's entrapment of officials and commoners, and local custom was rife with vendetta and resentment." },
  { zh: "延行改更，教以禮讓；", literal: "Yan practiced reform and renewal, teaching by courtesy and yielding;", idiomatic: "Yanshou carried out reforms and taught the people courtesy and forbearance;" },
  { zh: "召故老，與議定嫁娶、喪祭儀品，略依古禮，不得過法。", literal: "summoned the old elders, jointly discussed and fixed marriage, funeral, and sacrifice ritual grades, broadly following ancient rites, not permitted to exceed the law.", idiomatic: "summoned the village elders, and with them set standards for weddings, funerals, and sacrifices, broadly following ancient rites without exceeding what the law allowed." },
  { zh: "百姓遵用其教。", literal: "The hundred surnames followed his teaching.", idiomatic: "The people followed his instruction." },
  { zh: "賣偶車馬、下-{里}-偽物者，棄之市道。", literal: "Those who sold puppet carriages and horses and lower-{li}-sham goods discarded them on market roads.", idiomatic: "Those who sold toy carriages and horses and shoddy counterfeit goods cast them aside in the streets." },
  { zh: "黃霸代延壽居穎川，霸因其跡而大治。", literal: "Huang Ba replaced Yanshou in dwelling at Yingchuan; Ba took his traces and greatly governed.", idiomatic: "Huang Ba succeeded Yanshou in Yingchuan and, following his path, brought the commandery to great order." },
  { zh: "延壽為吏，上禮義，好古教化，所至必聘其賢士，以禮待，用廣謀議，納諫爭；", literal: "Yanshou as an official elevated ritual propriety, loved ancient transformation and education; wherever he arrived he always visited worthy scholars, treated them with courtesy, employed broad deliberation, and received remonstrance and contention;", idiomatic: "As an official, Yanshou exalted ritual and propriety, loved ancient teaching and transformation, and wherever he went always sought out worthy men, received them with courtesy, drew on wide counsel, and accepted remonstrance;" },
  { zh: "表孝弟有行，修治學官，春秋鄉射，陳鐘鼓、管弦，盛升降、揖讓；", literal: "commended filial piety and brotherhood with conduct, repaired and administered study halls, spring and autumn district archery—displayed bells, drums, pipes, and strings, the full ascent-descent and bowing yield;", idiomatic: "commended filial sons and dutiful brothers of good conduct, repaired school halls, held spring and autumn district archery contests, arrayed bells, drums, pipes, and strings, and staged the full rites of ascent, descent, bowing, and yielding;" },
  { zh: "及都試講武，設斧鉞、旌旗，習射、御之事；", literal: "and at the capital examination martial exercises—set axes, yue, banners and flags, practiced shooting and charioteering;", idiomatic: "and at the metropolitan martial review he set out axes, yue, banners, and flags and drilled archery and charioteering;" },
  { zh: "治城郭，收賦租，先明佈告其日；", literal: "governed city walls and moats, collected rent and tax, first clearly announced the days;", idiomatic: "repaired walls and moats, collected taxes and rents, and first posted clear notice of the due dates;" },
  { zh: "以期會為大事。", literal: "regarded scheduled assemblies as great affairs.", idiomatic: "and treated punctual attendance at official assemblies as a matter of the highest importance." },
  { zh: "吏民敬畏，趨嚮之。", literal: "Officials and people stood in awe and hastened toward them.", idiomatic: "Officials and commoners stood in awe and hastened to comply." },
  { zh: "又置正、五長，相率以孝弟；", literal: "Also established Rectifiers and Five-group heads, leading one another in filial piety and brotherhood;", idiomatic: "He also appointed Rectifiers and Five-group heads to lead one another in filial piety and brotherly duty;" },
  { zh: "不得捨奸人，閭裡阡陌有非常，吏輒聞知，奸人莫敢入界。", literal: "not permitted to harbor evil men; in lanes and paths on the fields if there was something unusual, officials at once heard and knew—evil men did not dare enter the border.", idiomatic: "and forbade sheltering wrongdoers. If anything unusual happened in lanes or fields, officials heard of it at once, and evildoers did not dare enter his jurisdiction." },
  { zh: "其始若煩，後吏無追捕之苦，民無箠楚之憂，皆便安之。", literal: "At first it seemed troublesome; afterward officials had no pursuit-and-capture hardship, the people no beating-and-flogging worry—all found it convenient and peaceful.", idiomatic: "At first the system seemed burdensome, but later officials were spared the pain of constant pursuit, and the people were spared fear of the rod; all found it convenient and secure." },
  { zh: "接待下吏，恩施甚厚而約誓明。", literal: "In receiving and treating subordinate officials, kindness and grace were very generous yet covenants and oaths were clear.", idiomatic: "In dealing with subordinates he was generous in grace yet exact in his expectations." },
  { zh: "或欺負之者，延壽痛自刻責：「豈其負之，何以至此！", literal: "If some deceived and bullied them, Yanshou painfully blamed himself: \"Was it perhaps I who failed them—how did it come to this!", idiomatic: "When any were wronged or bullied, Yanshou bitterly blamed himself: \"Did I fail them? How could it have come to this!\"" },
  { zh: "」吏聞者自傷悔，其縣尉至自刺死。", literal: "\" Officials who heard it themselves felt wounded remorse; some county assistants and magistrates even stabbed themselves to death.", idiomatic: "\" Officials who heard this were stricken with remorse; some county assistants and magistrates even stabbed themselves to death." },
  { zh: "及門下掾自剄，人救不殊，延壽涕泣，遣吏醫治視，厚復其家。", literal: "And gatehouse clerks cut their own throats—people rescued them but they did not die; Yanshou wept tears, sent officials to treat and view them, and generously compensated their families.", idiomatic: "Some of his own clerks cut their throats; though rescued, they nearly died. Yanshou wept, sent physicians to treat them, and richly compensated their families." },
  { zh: "在東郡三歲，令行禁止，斷獄大減，由是入為馮翊。", literal: "In Dongjun for three years, orders ran and prohibitions stood, criminal cases greatly diminished—thereby he entered office as Governor of Jingzhao.", idiomatic: "After three years in Dong Commandery, his orders were obeyed and prohibitions enforced, and criminal cases fell sharply; on that account he was appointed Governor of Jingzhao." },
  { zh: "延壽出行縣至高陵，民有昆弟相與訟田，自言。", literal: "Yanshou on a tour of the counties reached Gaoling; among the people were brothers suing each other over fields, each stating his own case.", idiomatic: "While touring his counties Yanshou reached Gaoling, where brothers were suing each other over farmland, each pleading his own case." },
  { zh: "延壽大傷之，曰：「幸得備位，為郡表率，不能宣明教化，至令民有骨肉爭訟，既傷風化，重使賢長吏、嗇夫、三老、孝弟受其恥，咎在馮翊，當先退。", literal: "Yanshou was greatly pained and said: \"Fortunately to hold a post as the commandery's model—unable to proclaim and clarify transformation and teaching, until making the people have flesh-and-bone litigation; it already injures customs and transformation, and furthermore makes worthy senior officials, revenue clerks, Three Elders, and Filial Piety bear this shame—the fault lies with the Governor of Jingzhao; I ought first withdraw.", idiomatic: "Yanshou was deeply grieved and said, \"Fortunate as I am to hold office as the commandery's exemplar, I have failed to proclaim and clarify moral teaching until the people sue their own flesh and blood. This already injures custom and teaching, and further shames worthy senior officials, revenue clerks, Three Elders, and leaders of filial piety. The fault lies with the Governor of Jingzhao; I ought to withdraw first.\"" },
  { zh: "」是日，移病不聽事，因入臥傳舍，閉閤思過。", literal: "\" That day he moved his illness and did not hear cases; thereupon entered and lay in the relay lodge, closed the gate, and pondered his faults.", idiomatic: "\" That same day he pleaded illness and ceased to hear cases; he withdrew to the relay lodge, closed the door, and reflected on his faults." },
  { zh: "一縣莫知所為，令、丞、嗇夫、三老亦皆自系待罪。", literal: "The whole county did not know what to do; the magistrate, assistant, revenue clerk, and Three Elders also all bound themselves awaiting punishment.", idiomatic: "The whole county was at a loss; the magistrate, assistant, revenue clerk, and Three Elders all bound themselves to await punishment." },
  { zh: "於是訟者宗族傳相責讓；", literal: "Thereupon the litigants' clans passed along mutual blame and reproach;", idiomatic: "Thereupon the litigants' clans passed along mutual blame and reproach;" },
  { zh: "此兩昆弟深自悔，皆自髡，肉袒謝，願以田相移，終死不敢復爭。", literal: "these two brothers deeply repented themselves—both shaved their heads, bared their torsos and apologized, wished to transfer fields to each other, and to the end of death did not dare contend again.", idiomatic: "the two brothers deeply repented, shaved their heads, bared their torsos in apology, offered to yield the fields to each other, and swore never to dispute again as long as they lived." },
  { zh: "郡中歙然，莫不傳相敕厲，不敢犯。", literal: "In the commandery all were harmonious; none failed to pass along admonition and encouragement, not daring to offend.", idiomatic: "Throughout the commandery harmony prevailed; everyone passed along admonition and encouragement, and none dared to offend." },
  { zh: "延壽恩信周遍二十四縣，莫敢以辭訟自言者。", literal: "Yanshou's grace and trust pervaded all twenty-four counties—none dared to bring forth litigation stating their own case.", idiomatic: "Yanshou's grace and trust spread through all twenty-four counties, and none dared to bring a lawsuit forward on his own behalf." },
  { zh: "推其至誠，吏民不忍欺紿。", literal: "Pushing his utmost sincerity, officials and people could not bear to deceive him.", idiomatic: "Such was his utmost sincerity that officials and commoners could not bear to deceive him." },
  { zh: "----5匈奴單于又殺先賢撣兩弟；", literal: "----5 The Xiongnu Chanyu again killed Xianxian Chan's two younger brothers;", idiomatic: "----5 The Xiongnu chanyu again killed two younger brothers of Xianxian Chan;" },
  { zh: "烏禪幕請之，不聽，心恚。", literal: "Wuchanmu requested them—not listened to; heart resentful.", idiomatic: "Wuchanmu asked for their bodies, but he would not listen, and her heart filled with resentment." },
  { zh: "其後左奧鞬王死，單于自立其小子為奧鞬王，留庭。", literal: "Afterward the Left Aojian King died; the Chanyu himself established his young son as Aojian King and kept him at court.", idiomatic: "Later the Left Aojian king died; the chanyu installed his young son as Aojian king and kept him at court." },
  { zh: "奧鞬貴人共立故奧鞬王子為王，與俱東徙。", literal: "Aojian nobles jointly established the former Aojian king's son as king and with him together moved east.", idiomatic: "The Aojian nobles jointly made the former Aojian king's son their king and moved east with him." },
  { zh: "單于右丞相將萬騎往擊之，失亡數千人，不勝。", literal: "The Chanyu's Right Chancellor led ten thousand cavalry to go strike them, lost several thousand men, and did not prevail.", idiomatic: "The chanyu's right chancellor led ten thousand horsemen to attack them, lost several thousand men, and was defeated." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
